window.addEventListener('load',()=>{
  // Try immediately from localStorage
  if(tryRestoreSession())return;
  // If Firebase loads users, try again
  document.addEventListener('fb-ready',()=>{
    setTimeout(()=>{
      if(!currentUser)tryRestoreSession();
    },800);
  },{once:true});
});
