function getUsers(){try{return JSON.parse(localStorage.getItem('tl_v6')||'{}');}catch(e){return{};}}
function saveUsers(u){try{localStorage.setItem('tl_v6',JSON.stringify(u));}catch(e){}}
async function syncUsersFromFirebase(){
  if(!window.FB_READY||!window.FB.getAllUsers)return;
  try{const fbUsers=await window.FB.getAllUsers();if(fbUsers&&Object.keys(fbUsers).length>0){const local=getUsers();Object.assign(local,fbUsers);saveUsers(local);}}catch(e){}
}
function getFpChecks(c){try{return JSON.parse(localStorage.getItem('tl_fp_'+c)||'{}');}catch(e){return{};}}
function saveFpChecks(c,d){
  try{localStorage.setItem('tl_fp_'+c,JSON.stringify(d));}catch(e){}
  if(window.FB_READY&&window.FB.saveCompliance){
    window.FB.saveCompliance(c,{checks:d,updatedAt:new Date().toISOString()}).catch(()=>{});
  }
}
function getTracker(k){try{return JSON.parse(localStorage.getItem('tl_trk_'+k)||'[]');}catch(e){return[];}}
function saveTracker(k,d){try{localStorage.setItem('tl_trk_'+k,JSON.stringify(d));}catch(e){}}
function now(){return new Date().toISOString();}
function todayStr(){return new Date().toISOString().slice(0,10);}
function daysUntil(s){const d=new Date(s),t=new Date();t.setHours(0,0,0,0);return Math.round((d-t)/86400000);}
function daysFrom(s){return Math.abs(daysUntil(s));}
function fmtDate(iso){if(!iso)return'Never';const d=new Date(iso),diff=Math.floor((Date.now()-d)/60000);if(diff<2)return'Just now';if(diff<60)return diff+'m ago';if(diff<1440)return Math.floor(diff/60)+'h ago';return Math.floor(diff/1440)+'d ago';}
function fmtLastActive(ts){
  if(!ts)return'Never logged in';
  const d=new Date(ts);
  const diffDays=Math.floor((Date.now()-d)/86400000);
  if(diffDays===0)return'Last seen: Today';
  if(diffDays===1)return'Last seen: Yesterday';
  return'Last seen: '+diffDays+' days ago';
}
function getBdayInfo(dob){if(!dob)return null;const t=new Date(),d=new Date(dob),ty=new Date(t.getFullYear(),d.getMonth(),d.getDate()),ny=new Date(t.getFullYear()+1,d.getMonth(),d.getDate()),tm=new Date(t.getFullYear(),t.getMonth(),t.getDate());const diff=Math.round((ty-tm)/86400000);const du=diff<0?Math.round((ny-tm)/86400000):diff;const age=t.getFullYear()-d.getFullYear();const ta=diff<=0?age:age+1;const mo=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return{daysUntil:du,isToday:du===0,dateStr:d.getDate()+' '+mo[d.getMonth()],turningAge:ta};}
function showAlert(m,t){const el=document.getElementById('alertBox');el.textContent=m;el.className='alert '+t;}
function clearAlert(){const el=document.getElementById('alertBox');el.className='alert';el.textContent='';}
function switchTab(t){clearAlert();document.getElementById('loginForm').style.display=t==='login'?'block':'none';document.getElementById('registerForm').style.display=t==='register'?'block':'none';document.getElementById('changePassForm').style.display=t==='changepass'?'block':'none';document.getElementById('tabLogin').className='tab'+(t==='login'?' active':'');document.getElementById('tabRegister').className='tab'+(t==='register'?' active':'');document.getElementById('tabChangePass').className='tab'+(t==='changepass'?' active':'');}
function validateCode(c){return/^SKA\d{6,}$/i.test(c.trim());}

function doRegister(){
  clearAlert();
  const name=document.getElementById('regName').value.trim(),email=document.getElementById('regEmail').value.trim(),code=document.getElementById('regCode').value.trim().toUpperCase(),dob=document.getElementById('regDob').value,dofa=document.getElementById('regDofa').value,pass=document.getElementById('regPass').value,pass2=document.getElementById('regPass2').value;
  const photo=document.getElementById('regPhoto')?._b64||null;
  if(!photo)return showAlert('Please upload a profile photo — tap the circle above your name.','error');
  if(!name)return showAlert('Please enter your full name.','error');
  if(!email||!email.includes('@'))return showAlert('Please enter a valid email address.','error');
  if(!validateCode(code))return showAlert('Employee code must be SKA followed by numbers, e.g. SKA310199.','error');
  if(!APPROVED_CODES.has(code))return showAlert('This employee code is not on the approved advisor list. Please contact your manager to get access.','error');
  if(!dob)return showAlert('Please enter your date of birth.','error');
  if(!dofa)return showAlert('Please enter your DOFA date (date of first appointment).','error');
  if(pass.length<6)return showAlert('Password must be at least 6 characters.','error');
  if(pass!==pass2)return showAlert('Passwords do not match.','error');
  const users=getUsers();if(users[code])return showAlert('This employee code is already registered.','error');
  users[code]={name,email,code,dob,dofa,pass,photo,isManager:false,isOps:false,registeredAt:now(),lastActive:null};
  saveUsers(users);
  if(window.FB_READY){window.FB.saveUser(code,users[code]).catch(()=>{});}
  showAlert('Account created! Signing you in...','success');
  setTimeout(()=>{switchTab('login');document.getElementById('loginCode').value=code;},1400);
}

function doLogin(){
  clearAlert();
  const code=document.getElementById('loginCode').value.trim().toUpperCase(),pass=document.getElementById('loginPass').value;
  if(!code)return showAlert('Please enter your employee code.','error');
  if(!pass)return showAlert('Please enter your password.','error');
  if(!APPROVED_CODES.has(code)&&code!=='PURSHIVILLE'&&code!=='ARLENE')return showAlert('Access denied. Your employee code is not on the approved list. Please contact your manager.','error');
  if(code==='PURSHIVILLE'||code==='MANAGER')return enterHub({name:'Purshiville Nortje',email:'manager@teambuffalos.co.za',code:'PURSHIVILLE',pass,isManager:true,isOps:true,dob:null});
  if(code==='ARLENE'||code==='OPS')return enterHub({name:'Arlene',email:'arlene@teambuffalos.co.za',code:'ARLENE',pass,isManager:false,isOps:true,dob:null});
  const users=getUsers();
  if(users[code]){
    if(users[code].pass!==pass)return showAlert('Incorrect password. Please try again.','error');
    if(users[code].isSuspended)return showAlert('Your access has been suspended. Please contact your manager.','error');
    users[code].lastActive=now();saveUsers(users);
    if(window.FB_READY&&window.FB.saveUser)window.FB.saveUser(code,users[code]).catch(()=>{});
    enterHub(users[code]);
    return;
  }
  // Not in local cache — fetch from Firebase
  if(window.FB_READY&&window.FB.getAllUsers){
    showAlert('Looking up your account…','info');
    window.FB.getAllUsers().then(fbUsers=>{
      clearAlert();
      if(!fbUsers||!fbUsers[code])return showAlert('Employee code not found. Please register first.','error');
      const local=getUsers();Object.assign(local,fbUsers);saveUsers(local);
      if(local[code].pass!==pass)return showAlert('Incorrect password. Please try again.','error');
      local[code].lastActive=now();saveUsers(local);
      if(window.FB.saveUser)window.FB.saveUser(code,local[code]).catch(()=>{});
      enterHub(local[code]);
    }).catch(()=>showAlert('Employee code not found. Please register first.','error'));
  } else {
    showAlert('Employee code not found. Please register first.','error');
  }
}



function updatePrecanHubAlert(){
  const el=document.getElementById('precanHubAlert');
  if(!el)return;
  if(!currentUser){el.style.display='none';return;}
  const now=new Date();
  const day=now.getDay(); // 0=Sun,6=Sat
  // Public holidays SA 2026 (yyyy-mm-dd)
  const ph=['2026-01-01','2026-03-21','2026-04-03','2026-04-06','2026-04-27','2026-05-01','2026-06-16','2026-08-09','2026-09-24','2026-12-16','2026-12-25','2026-12-26'];
  const today=now.toISOString().slice(0,10);
  const isWeekend=day===0||day===6;
  const isHoliday=ph.includes(today);
  if(isWeekend||isHoliday){
    // Show a calm "no pre-cans today" notice
    el.style.display='block';
    el.style.background='linear-gradient(135deg,#f0fdf4,#f8fff8)';
    el.style.border='1.5px solid #86efac';
    el.style.animation='none';
    el.style.cursor='default';
    el.onclick=null;
    el.innerHTML=`<div style="display:flex;align-items:center;gap:10px;">
      <span style="font-size:20px;">✅</span>
      <div>
        <div style="font-size:13px;font-weight:700;color:#166534;">No pre-cancellations today</div>
        <div style="font-size:11px;color:#4ade80;margin-top:2px;">${isHoliday?'Public holiday':'Weekend'} — pre-cancellations resume on the next working day</div>
      </div>
    </div>`;
  } else {
    el.style.display='block';
    el.style.background='linear-gradient(135deg,#fef2f2,#fff5f5)';
    el.style.border='1.5px solid #fca5a5';
    el.style.animation='glow 2s infinite';
    el.style.cursor='default';
    const today2=now.toISOString().slice(0,10);
    const doneKey='tl_precan_done_'+today2;
    const canMarkDone=currentUser.isOps||currentUser.isManager;
    const isDone=canMarkDone&&localStorage.getItem(doneKey)==='1';
    if(isDone){
      el.style.background='#f0fdf4';el.style.borderColor='#86efac';el.style.borderLeftColor='#16a34a';el.onclick=null;
      el.innerHTML=`<div style="display:flex;align-items:center;gap:10px;"><span style="font-size:22px;">✅</span><div><div style="font-size:13px;font-weight:700;color:#16a34a;">Pre-cancellations completed for today</div><div style="font-size:11px;color:#166534;margin-top:2px;"><a href="#" onclick="event.preventDefault();localStorage.removeItem('${doneKey}');updatePrecanHubAlert();" style="color:#166534;">Undo</a></div></div></div>`;
    } else {
      el.style.background='linear-gradient(135deg,#fef2f2,#fff5f5)';el.style.borderColor='#fca5a5';el.onclick=null;
      if(canMarkDone){
        el.innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;">
          <div style="display:flex;align-items:center;gap:10px;cursor:pointer;" onclick="window.open('https://docs.google.com/spreadsheets/d/1Wt8hpkJXs5cPRCGbSeZJaGOBFcZUjitIoizkssPMJ1E/edit?usp=drivesdk','_blank')">
            <span style="font-size:22px;">⚠️</span>
            <div><div style="font-size:13px;font-weight:700;color:#dc2626;">Pre-Cancellations — Check Required</div>
            <div style="font-size:11px;color:#991b1b;margin-top:2px;">Tap to open Pavlov sheet · Work the list before 12:00</div></div>
          </div>
          <label style="display:flex;align-items:center;gap:6px;cursor:pointer;background:#fff;border:1px solid #fca5a5;border-radius:8px;padding:6px 10px;white-space:nowrap;" onclick="event.stopPropagation()"><input type="checkbox" onchange="if(this.checked){localStorage.setItem('${doneKey}','1');updatePrecanHubAlert();}"/><span style="font-size:11px;font-weight:700;color:#dc2626;">All done today</span></label>
        </div>`;
      } else {
        el.style.cursor='pointer';
        el.onclick=()=>window.open('https://docs.google.com/spreadsheets/d/1Wt8hpkJXs5cPRCGbSeZJaGOBFcZUjitIoizkssPMJ1E/edit?usp=drivesdk','_blank');
        el.innerHTML=`<div style="display:flex;align-items:center;gap:10px;">
          <span style="font-size:22px;">⚠️</span>
          <div>
            <div style="font-size:13px;font-weight:700;color:#dc2626;">Pre-Cancellations — Check if you're on the list</div>
            <div style="font-size:11px;color:#991b1b;margin-top:2px;">Tap to open the Pavlov sheet · Deadline 12:00</div>
          </div>
          <span style="margin-left:auto;font-size:16px;color:#dc2626;">›</span>
        </div>`;
      }
    }
  }
}

