function enterHub(user){
  // Keep lastActive fresh in Firebase so the manager roster is accurate
  const _users=getUsers();
  if(_users[user.code]){
    _users[user.code].lastActive=now();
    saveUsers(_users);
    user=_users[user.code];
    if(window.FB_READY&&window.FB.saveUser)window.FB.saveUser(user.code,_users[user.code]).catch(()=>{});
  }
  requestNotificationPermission();
  startInactivityTimer();
  // Load compliance from Firebase
  if(window.FB_READY&&window.FB.getCompliance){
    window.FB.getCompliance(user.code).then(data=>{
      if(data&&data.checks){
        try{localStorage.setItem('tl_fp_'+user.code,JSON.stringify(data.checks));}catch(e){}
      }
    }).catch(()=>{});
  }
  currentUser=user;
  updateTopbarAvatar();
  // Persist session so refresh doesn't log out
  try{localStorage.setItem('tl_session',JSON.stringify({code:user.code,pass:user.pass}));}catch(e){}
  document.getElementById('authScreen').classList.remove('active');
  document.getElementById('hubMain').style.display='flex';
  const unEl=document.getElementById('userName');if(unEl)unEl.textContent=user.name.split(' ')[0];
  const uaEl=document.getElementById('userAvatar');if(uaEl)uaEl.textContent=user.name.charAt(0).toUpperCase();
  // managerTab removed — Team is inside opsland
  // teamTile removed — inside opsland
  // Ops tab only for manager/Arlene; advisors use Tools instead
  document.getElementById('opsTab').style.display=(user.isManager||user.isOps)?'inline-block':'none';
  const toolMgrSec=document.getElementById('toolMgrSection');if(toolMgrSec)toolMgrSec.style.display=(user.isManager||user.isOps)?'block':'none';
  const bTab=document.getElementById('budgetTab');if(bTab)bTab.style.display='none';
  const tmTab=document.getElementById('teamTab');if(tmTab)tmTab.style.display=(user.isManager||user.isOps)?'inline-block':'none';
  // More dropdown role-aware items
  const budgetMore=document.getElementById('budgetMoreItem');if(budgetMore)budgetMore.style.display='flex';
  const scCard=document.getElementById('toolSpotcheck');if(scCard)scCard.style.display=user.isManager?'block':'none';
  const ntuCard=document.getElementById('toolNTU');if(ntuCard)ntuCard.style.display=(user.isManager||user.isOps)?'block':'none';
  const drCard=document.getElementById('toolDailyRegion');if(drCard)drCard.style.display=user.isManager?'block':'none';
  const hqn=document.getElementById('hubQuickNotice');if(hqn)hqn.style.display=(user.isManager||user.isOps)?'block':'none';
  const advisorOpts=ADVISOR_LIST.map(a=>`<option value="${a.code}">${a.name}</option>`).join('');
  ['hubNoticeRecipient','noticeRecipient'].forEach(id=>{const s=document.getElementById(id);if(s){s.innerHTML=`<option value="ALL">👥 All advisors</option>${advisorOpts}`;}});
  const inboxBtn=document.getElementById('inboxBtn');if(inboxBtn)inboxBtn.style.display='flex';
  const chatBtn=document.getElementById('chatBtn');if(chatBtn)chatBtn.style.display='flex';
  const opsTileEl=document.getElementById('opsTile');if(opsTileEl)opsTileEl.style.display='block';
  // Manager-only sub-tiles inside opsland
  ['oltDailyOps','oltTeam','oltRecruit','oltPrecan','opsTodaySnapshot','oltStats'].forEach(id=>{
    const el=document.getElementById(id);if(el)el.style.display=(user.isOps||user.isManager)?'block':'none';
  });
  chatHistory=[];
  const fn=user.name.split(' ')[0];
  const bday=user.dob?getBdayInfo(user.dob):null;
  let greeting=`Hi ${fn}! I'm the Team Buffalos business assistant.`;
  if(bday&&bday.isToday)greeting=`🎂 Happy Birthday ${fn}! Wishing you a wonderful day from the whole Team Buffalos family! I'm also here for any business questions.`;
  document.getElementById('chatMessages').innerHTML=`<div class="msg bot"><div class="msg-av bot">AI</div><div class="msg-bubble">${greeting} Ask me anything about products, commission, NTU, persistency, Qlink, pre-cancellations, fit &amp; proper, or compliance — I'm here 24/7.</div></div>`;
  renderFpPage();renderHubBirthdays();
  // Sync from Firebase then render
  if(window.FB_READY){
    Promise.all([
      syncUsersFromFirebase(),
      syncSchedulesFromFirebase(),
      syncDocsFromFirebase(),
    ]).then(()=>{
      renderNoticeBoard();
      if(currentUser.isOps||currentUser.isManager){renderOpsPage();renderManagerDash();populateStatsAdvisorSelect();}
      initStatsListener();
    }).catch(e=>{console.warn('Sync error:',e);renderNoticeBoard();});
    window.startNoticeListener();
    if(window.startTop3Listener)window.startTop3Listener();
    startInboxListener();
    startSentListener();
    startChatListListener();
    window.startDocListener();
  } else {
    document.addEventListener('fb-ready',()=>{
      Promise.all([syncUsersFromFirebase(),syncSchedulesFromFirebase(),syncDocsFromFirebase()])
        .then(()=>{renderNoticeBoard();}).catch(()=>{});
      window.startNoticeListener();
      if(window.startTop3Listener)window.startTop3Listener();
      startInboxListener();
      startSentListener();
      startChatListListener();
      window.startDocListener();
    },{once:true});
    renderNoticeBoard();
  }
  renderOpsLand();
  if(user.isOps)renderOpsPage();
  showPage('hub');
  updateWelcomeBar();
  updatePrecanHubAlert();
  renderBibleVerse();
  renderHubCountdown();
  renderHubPaymentReminder();
  renderProdCountdownStandalone();
  renderDailyBrief();
  renderTop3();
  renderYTDStats();
  // Show broadcast button for manager/ops
  const bcBtn=document.getElementById('chatBroadcastBtn');if(bcBtn)bcBtn.style.display=(user.isManager||user.isOps)?'inline-block':'none';
}

// ── INACTIVITY TIMER ──
let _inactivityTimer = null;
let _inactivityWarnTimer = null;
const INACTIVITY_LOGOUT_MS = 30 * 60 * 1000;  // 30 minutes
const INACTIVITY_WARN_MS   = 25 * 60 * 1000;  // warn at 25 minutes

function resetInactivityTimer(){
  if(!currentUser) return;
  clearTimeout(_inactivityTimer);
  clearTimeout(_inactivityWarnTimer);
  document.getElementById('inactivityWarning').style.display = 'none';
  _inactivityWarnTimer = setTimeout(()=>{
    if(currentUser){
      document.getElementById('inactivityWarning').style.display = 'flex';
    }
  }, INACTIVITY_WARN_MS);
  _inactivityTimer = setTimeout(()=>{
    if(currentUser){
      document.getElementById('inactivityWarning').style.display = 'none';
      doLogout();
    }
  }, INACTIVITY_LOGOUT_MS);
}

function startInactivityTimer(){
  ['mousemove','keydown','touchstart','click'].forEach(ev=>{
    document.addEventListener(ev, resetInactivityTimer, {passive:true});
  });
  resetInactivityTimer();
}

function stopInactivityTimer(){
  clearTimeout(_inactivityTimer);
  clearTimeout(_inactivityWarnTimer);
  _inactivityTimer = null;
  _inactivityWarnTimer = null;
  ['mousemove','keydown','touchstart','click'].forEach(ev=>{
    document.removeEventListener(ev, resetInactivityTimer);
  });
  const warn = document.getElementById('inactivityWarning');
  if(warn) warn.style.display = 'none';
}

function doLogout(){
  stopInactivityTimer();
  if(_inboxUnsub){_inboxUnsub();_inboxUnsub=null;}
  if(_chatListUnsub){_chatListUnsub();_chatListUnsub=null;}
  if(_chatThreadUnsub){_chatThreadUnsub();_chatThreadUnsub=null;}
  const inboxBtn=document.getElementById('inboxBtn');if(inboxBtn)inboxBtn.style.display='none';
  const chatBtn=document.getElementById('chatBtn');if(chatBtn)chatBtn.style.display='none';
  window._inboxMsgs=[];window._myChats=[];
  currentUser=null;chatHistory=[];
  try{localStorage.removeItem('tl_session');}catch(e){}
  document.getElementById('hubMain').style.display='none';
  document.getElementById('authScreen').classList.add('active');
  clearAlert();
  document.getElementById('loginCode').value='';
  document.getElementById('loginPass').value='';
  showPage('hub');
}

function setupStandardHero(){
  const hero=document.getElementById('stdBufHero');
  if(!hero||hero.dataset.loaded)return;
  try{
    const bg=getComputedStyle(document.body,'::before').backgroundImage;
    if(bg&&bg!=='none'){
      hero.style.backgroundImage=bg;
      hero.style.backgroundSize='cover';
      hero.style.backgroundPosition='center 40%';
      hero.dataset.loaded='1';
    }
  }catch(e){}
}
// ── PRODUCTION STATS ──────────────────────────────────────────────────
function getStatsPeriod(){
  const m=document.getElementById('statsPeriodMonth');
  const y=document.getElementById('statsPeriodYear');
  if(m&&y)return y.value+'-'+m.value.padStart(2,'0');
  const now=new Date();
  return now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
}
function formatPeriodLabel(period){
  const [y,m]=period.split('-');
  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  return(months[parseInt(m)-1]||m)+' '+y;
}
function openStatsModal(){
  const overlay=document.getElementById('statsModalOverlay');
  if(overlay){overlay.style.display='flex';}
  const now=new Date();
  const mo=document.getElementById('statsPeriodMonth');
  const yr=document.getElementById('statsPeriodYear');
  if(mo)mo.value=('0'+(now.getMonth()+1)).slice(-2);
  if(yr)yr.value=String(now.getFullYear());
  populateStatsAdvisorSelect();
  refreshStatsPeriod();
  populateTop3Selects();
}
function closeStatsModal(){
  const overlay=document.getElementById('statsModalOverlay');
  if(overlay)overlay.style.display='none';
}
function populateStatsAdvisorSelect(){
  const sel=document.getElementById('statsAdvisorSelect');
  if(!sel)return;
  const users=getUsers();
  // Always use the full whitelist — fall back to registered name if available
  sel.innerHTML='<option value="">— Select advisor —</option>'+
    ADVISOR_LIST.map(a=>{
      const reg=users[a.code];
      const name=reg?.name||a.name;
      return`<option value="${a.code}">${name}</option>`;
    }).join('');
}
function refreshStatsPeriod(){
  const period=getStatsPeriod();
  window._currentPeriodStats={advisors:{}};
  // Reset advisor select so stale data doesn't show
  const sel=document.getElementById('statsAdvisorSelect');
  if(sel)sel.value='';
  const fields=document.getElementById('statsInputFields');
  if(fields)fields.style.display='none';
  const loading=document.getElementById('statsPeriodLoading');
  if(loading)loading.style.display='inline';
  if(window.FB_READY){
    if(window.startStatsListener)window.startStatsListener(period);
    setTimeout(()=>{if(loading)loading.style.display='none';},800);
  } else {
    try{window._currentPeriodStats=JSON.parse(localStorage.getItem('tl_prod_stats_'+period)||'{}');}catch(e){}
    renderProdStats(window._currentPeriodStats||{advisors:{}},period);
    renderStatsManagerPreview(window._currentPeriodStats||{advisors:{}});
    if(loading)loading.style.display='none';
  }
  prefillTop3Form();
}
function loadStatsForAdvisor(){
  const code=document.getElementById('statsAdvisorSelect')?.value;
  const fields=document.getElementById('statsInputFields');
  if(!code){if(fields)fields.style.display='none';return;}
  if(fields)fields.style.display='block';
  const adv=(window._currentPeriodStats?.advisors||{})[code]||{};
  document.getElementById('si_targetCases').value=adv.targetCases!==undefined?adv.targetCases:'';
  document.getElementById('si_actualCases').value=adv.actualCases!==undefined?adv.actualCases:'';
  document.getElementById('si_targetPrem').value=adv.targetPremium!==undefined?adv.targetPremium:'';
  document.getElementById('si_actualPrem').value=adv.actualPremium!==undefined?adv.actualPremium:'';
  document.getElementById('si_ntu4').value=adv.ntu4Month!=null?adv.ntu4Month:'';
  document.getElementById('si_ntu15').value=adv.ntu15Month!=null?adv.ntu15Month:'';
  document.getElementById('si_persistency').value=adv.persistency!=null?adv.persistency:'';
}
async function saveAdvisorStats(){
  const code=document.getElementById('statsAdvisorSelect')?.value;
  if(!code)return showAlert('Please select an advisor.','error');
  const period=getStatsPeriod();
  const users=getUsers();
  const whitelisted=ADVISOR_LIST.find(a=>a.code===code);
  const user=users[code];
  const _pct=id=>{const v=(document.getElementById(id)?.value||'').replace('%','').trim();return v!==''?parseFloat(v):null;};
  const data={
    code,name:user?.name||whitelisted?.name||code,
    targetCases:Number(document.getElementById('si_targetCases').value)||0,
    actualCases:Number(document.getElementById('si_actualCases').value)||0,
    targetPremium:Number(document.getElementById('si_targetPrem').value)||0,
    actualPremium:Number(document.getElementById('si_actualPrem').value)||0,
    ntu4Month:_pct('si_ntu4'),
    ntu15Month:_pct('si_ntu15'),
    persistency:_pct('si_persistency'),
    updatedBy:currentUser?.name||'Manager',
    updatedAt:new Date().toISOString()
  };
  if(window.FB_READY){
    try{
      await window.FB.saveStats(period,code,data);
      const fb=document.getElementById('statsSaveFeedback');
      if(fb){fb.style.display='block';setTimeout(()=>fb.style.display='none',2500);}
      // Notify the advisor their stats were updated
      const adv=ADVISOR_LIST.find(a=>a.code===code);
      if(adv){
        const ntuStr=(data.ntu4Month!=null?` | 4M NTU: ${data.ntu4Month}%`:'')+(data.ntu15Month!=null?` | 15M NTU: ${data.ntu15Month}%`:'');
        const persStr=data.persistency!=null?` | Persistency: ${data.persistency}%`:'';
        window.FB.sendInbox({to:code,from:currentUser.code,fromName:currentUser.name,title:'Your production stats were updated',body:`${formatPeriodLabel(period)} — Cases: ${data.actualCases}/${data.targetCases} | Premium: R${data.actualPremium.toLocaleString()}/R${data.targetPremium.toLocaleString()}${ntuStr}${persStr}`,type:'stats'}).catch(()=>{});
      }
    }catch(e){showAlert('Error: '+e.message,'error');}
  } else {
    const key='tl_prod_stats_'+period;
    let stored={advisors:{}};
    try{stored=JSON.parse(localStorage.getItem(key)||'{"advisors":{}}')}catch(e){}
    stored.advisors[code]=data;
    localStorage.setItem(key,JSON.stringify(stored));
    window._currentPeriodStats=stored;
    renderProdStats(stored,period);
    renderStatsManagerPreview(stored);
    renderYTDStats();
    const fb=document.getElementById('statsSaveFeedback');
    if(fb){fb.style.display='block';setTimeout(()=>fb.style.display='none',2500);}
  }
}
function initStatsListener(){
  const now=new Date();
  const period=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
  // Set current month in manager selectors
  const mm=document.getElementById('statsPeriodMonth');
  const yy=document.getElementById('statsPeriodYear');
  if(mm)mm.value=String(now.getMonth()+1).padStart(2,'0');
  if(yy)yy.value=String(now.getFullYear());
  if(window.FB_READY&&window.startStatsListener){
    window.startStatsListener(period);
  } else {
    try{window._currentPeriodStats=JSON.parse(localStorage.getItem('tl_prod_stats_'+period)||'{}');}catch(e){}
    renderProdStats(window._currentPeriodStats||{advisors:{}},period);
    renderStatsManagerPreview(window._currentPeriodStats||{advisors:{}});
  }
}
function renderProdStats(data,period){
  const personalEl=document.getElementById('hubProdStats');
  const teamEl=document.getElementById('hubTeamStats');
  if(!personalEl||!teamEl||!currentUser)return;
  const periodLabel=formatPeriodLabel(period);
  const advisors=Object.values(data?.advisors||{}).filter(a=>!REVOKED_CODES.has(a.code));
  if(!advisors.length){personalEl.style.display='none';teamEl.style.display='none';return;}

  // ── Personal mini card ──
  const my=data?.advisors?.[currentUser.code];
  if(my){
    const cp=my.targetCases?Math.min(Math.round(my.actualCases/my.targetCases*100),100):0;
    const pp=my.targetPremium?Math.min(Math.round(my.actualPremium/my.targetPremium*100),100):0;
    const cc=cp>=100?'#16a34a':cp>=70?'#c9922a':'#dc2626';
    const pc=pp>=100?'#16a34a':pp>=70?'#c9922a':'#dc2626';
    personalEl.style.display='block';
    const _chip=(val,label,good)=>val!=null?`<div style="display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:700;padding:3px 8px;border-radius:8px;background:${good?'#f0fdf4':'#fef2f2'};color:${good?'#16a34a':'#dc2626'};border:1px solid ${good?'#86efac':'#fca5a5'};">${label} ${val}%</div>`:'';
    const ntu4Chip=_chip(my.ntu4Month,'4M NTU',my.ntu4Month<15);
    const ntu15Chip=_chip(my.ntu15Month,'15M NTU',my.ntu15Month<15);
    const persChip=_chip(my.persistency,'Pers',my.persistency>65);
    const chips=(ntu4Chip||ntu15Chip||persChip)?`<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;padding-top:8px;border-top:1px solid #f4f2ed;">${ntu4Chip}${ntu15Chip}${persChip}</div>`:'';
    personalEl.innerHTML=`<div class="prod-stats-card"><div class="prod-stats-hd"><div class="prod-stats-title">📊 My Production — ${periodLabel}</div><div class="prod-stats-period">Updated by ${my.updatedBy||'manager'}</div></div><div class="prod-stat-row"><div class="prod-stat-cell"><div class="prod-stat-label">Cases</div><div class="prod-stat-val" style="color:${cc};">${my.actualCases}</div><div class="prod-stat-target">of ${my.targetCases} target</div><div class="prod-stat-bar-wrap"><div class="prod-stat-bar" style="width:${cp}%;background:${cc};"></div></div><div class="prod-stat-pct" style="color:${cc};">${cp}%</div></div><div class="prod-stat-cell"><div class="prod-stat-label">Risk Premium</div><div class="prod-stat-val" style="color:${pc};font-size:${my.actualPremium>=10000?'16px':'20px'};">R${my.actualPremium.toLocaleString()}</div><div class="prod-stat-target">of R${my.targetPremium.toLocaleString()} target</div><div class="prod-stat-bar-wrap"><div class="prod-stat-bar" style="width:${pp}%;background:${pc};"></div></div><div class="prod-stat-pct" style="color:${pc};">${pp}%</div></div></div>${chips}</div>`;
  } else {
    personalEl.style.display='none';
  }

  // ── Rankings ──
  teamEl.style.display='block';
  const medals=['🥇','🥈','🥉'];

  // Most Premiums
  const byPrem=[...advisors].sort((a,b)=>(b.actualPremium||0)-(a.actualPremium||0));
  const premRows=byPrem.map((a,i)=>{
    const pp=a.targetPremium?Math.min(Math.round(a.actualPremium/a.targetPremium*100),100):0;
    const pc=pp>=100?'#16a34a':pp>=70?'#c9922a':'#dc2626';
    const isMe=a.code===currentUser.code;
    return`<tr style="${isMe?'background:#fdf6ed;font-weight:700;':''}">`+
      `<td style="padding:8px 10px;font-size:13px;text-align:center;">${medals[i]||i+1}</td>`+
      `<td style="padding:8px 10px;font-size:12px;font-weight:${isMe?700:600};color:#0d1f3c;">${_advisorNameMap[a.code]||a.name}${isMe?' ★':''}${_newBadge(a.code)}</td>`+
      `<td style="padding:8px 10px;font-size:12px;font-weight:700;color:${pc};">R${(a.actualPremium||0).toLocaleString()}</td>`+
      `<td style="padding:8px 10px;font-size:11px;color:#6b7280;">${pp}%</td>`+
      `</tr>`;
  }).join('');

  // Most Cases
  const byCases=[...advisors].sort((a,b)=>(b.actualCases||0)-(a.actualCases||0));
  const caseRows=byCases.map((a,i)=>{
    const cp=a.targetCases?Math.min(Math.round(a.actualCases/a.targetCases*100),100):0;
    const cc=cp>=100?'#16a34a':cp>=70?'#c9922a':'#dc2626';
    const isMe=a.code===currentUser.code;
    return`<tr style="${isMe?'background:#fdf6ed;font-weight:700;':''}">`+
      `<td style="padding:8px 10px;font-size:13px;text-align:center;">${medals[i]||i+1}</td>`+
      `<td style="padding:8px 10px;font-size:12px;font-weight:${isMe?700:600};color:#0d1f3c;">${_advisorNameMap[a.code]||a.name}${isMe?' ★':''}${_newBadge(a.code)}</td>`+
      `<td style="padding:8px 10px;font-size:12px;font-weight:700;color:${cc};">${a.actualCases||0}</td>`+
      `<td style="padding:8px 10px;font-size:11px;color:#6b7280;">${cp}%</td>`+
      `</tr>`;
  }).join('');

  teamEl.innerHTML=
    `<div class="team-stats-card" style="margin-bottom:10px;"><div class="team-stats-hd"><div style="color:#f5d98b;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:2px;">💰 ${periodLabel}</div><div style="color:#fff;font-size:14px;font-weight:700;">Most Premiums</div></div><div style="overflow-x:auto;"><table class="team-stats-tbl"><thead><tr><th>#</th><th>Advisor</th><th>Premium</th><th>vs Target</th></tr></thead><tbody>${premRows}</tbody></table></div></div>`+
    `<div class="team-stats-card"><div class="team-stats-hd"><div style="color:#f5d98b;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:2px;">📋 ${periodLabel}</div><div style="color:#fff;font-size:14px;font-weight:700;">Most Cases</div></div><div style="overflow-x:auto;"><table class="team-stats-tbl"><thead><tr><th>#</th><th>Advisor</th><th>Cases</th><th>vs Target</th></tr></thead><tbody>${caseRows}</tbody></table></div></div>`;
}
function renderStatsManagerPreview(data){
  const el=document.getElementById('statsManagerPreview');
  if(!el)return;
  const advisors=Object.values(data?.advisors||{});
  if(!advisors.length){el.innerHTML='<div style="font-size:12px;color:#9ca3af;text-align:center;padding:8px 0;">No stats saved for this period yet.</div>';return;}
  el.innerHTML='<div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;padding-top:10px;border-top:1px solid #f4f2ed;">Current period — all advisors</div>'+
    '<div style="display:flex;flex-direction:column;gap:6px;">'+
    advisors.sort((a,b)=>(_advisorNameMap[a.code]||a.name).localeCompare(_advisorNameMap[b.code]||b.name)).map(a=>{
      const cp=a.targetCases?Math.round(a.actualCases/a.targetCases*100):0;
      const c=cp>=100?'#16a34a':cp>=70?'#c9922a':'#dc2626';
      const displayName=_advisorNameMap[a.code]||a.name;
      return`<div style="display:flex;align-items:center;justify-content:space-between;font-size:12px;padding:8px 10px;background:#f9f9f9;border-radius:8px;"><div style="font-weight:700;color:#0d1f3c;">${displayName}</div><div style="display:flex;gap:14px;"><span style="font-weight:700;color:${c};">${a.actualCases}/${a.targetCases} cases</span><span style="color:#6b7280;">R${a.actualPremium.toLocaleString()}/R${a.targetPremium.toLocaleString()}</span></div></div>`;
    }).join('')+'</div>';
}
function getYTDStats(){
  const ytd={};
  const now=new Date();
  const year=now.getFullYear();
  for(let m=1;m<=now.getMonth()+1;m++){
    const key='tl_prod_stats_'+year+'-'+(m<10?'0':'')+m;
    try{
      const d=JSON.parse(localStorage.getItem(key)||'null');
      if(!d?.advisors)continue;
      Object.entries(d.advisors).forEach(([code,a])=>{
        if(!ytd[code])ytd[code]={code,name:_advisorNameMap[code]||a.name||code,cases:0,premium:0};
        ytd[code].cases+=(a.actualCases||0);
        ytd[code].premium+=(a.actualPremium||0);
      });
    }catch(e){}
  }
  return Object.values(ytd).filter(a=>(a.cases>0||a.premium>0)&&!REVOKED_CODES.has(a.code));
}
function renderYTDStats(){
  const el=document.getElementById('hubYTD');
  if(!el||!currentUser)return;
  // Sync all months from Firebase then re-render
  if(window.FB_READY&&window.FB.getYearStats){
    const yr=String(new Date().getFullYear());
    window.FB.getYearStats(yr).then(fbMonths=>{
      Object.entries(fbMonths).forEach(([period,data])=>{
        const k='tl_prod_stats_'+period;
        try{
          const local=JSON.parse(localStorage.getItem(k)||'{"advisors":{}}');
          Object.assign(local.advisors||{},data.advisors||{});
          local.advisors=Object.assign({},data.advisors||{},local.advisors);
          localStorage.setItem(k,JSON.stringify({...data,...local}));
        }catch(e){localStorage.setItem('tl_prod_stats_'+period,JSON.stringify(data));}
      });
      _renderYTDStatsInner(el);
    }).catch(()=>_renderYTDStatsInner(el));
  } else {
    _renderYTDStatsInner(el);
  }
}
function _renderYTDStatsInner(el){
  const stats=getYTDStats();
  if(!stats.length){
    if(currentUser.isManager||currentUser.isOps){
      el.style.display='block';
      el.innerHTML=`<div style="background:#f9f9f9;border:1px dashed #d1d5db;border-radius:12px;padding:14px 16px;text-align:center;color:#6b7280;font-size:12px;">
        <div style="font-size:20px;margin-bottom:6px;">📊</div>
        <div style="font-weight:700;color:#374151;margin-bottom:4px;">No production stats yet for ${new Date().getFullYear()}</div>
        <div style="margin-bottom:10px;">Go to <b>Operations → Production Stats</b> and enter each advisor's monthly figures. Change the month selector to add historical data for January onwards.</div>
        <button onclick="closeStatsModal&&closeStatsModal();openStatsModal()" style="background:#0d1f3c;color:#fff;border:none;border-radius:8px;padding:8px 16px;font-size:12px;font-weight:700;cursor:pointer;">📊 Open Production Stats</button>
      </div>`;
    } else {
      el.style.display='none';
    }
    return;
  }
  el.style.display='block';
  const medals=['🥇','🥈','🥉'];
  const byPrem=[...stats].sort((a,b)=>b.premium-a.premium);
  const byCases=[...stats].sort((a,b)=>b.cases-a.cases);
  const my=stats.find(a=>a.code===currentUser.code);
  const n=stats.length;
  const myRankPrem=my?byPrem.findIndex(a=>a.code===currentUser.code)+1:0;
  const myRankCases=my?byCases.findIndex(a=>a.code===currentUser.code)+1:0;
  const yr=new Date().getFullYear();
  const myCard=my?`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px 14px;margin-bottom:8px;display:flex;align-items:stretch;">
    <div style="flex:1;text-align:center;padding:0 8px;"><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;margin-bottom:3px;">YTD Cases</div><div style="font-size:26px;font-weight:800;color:#0d1f3c;">${my.cases}</div><div style="font-size:10px;color:#6b7280;">#${myRankCases} of ${n}</div></div>
    <div style="width:1px;background:#f4f2ed;margin:0 4px;"></div>
    <div style="flex:1;text-align:center;padding:0 8px;"><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;margin-bottom:3px;">YTD Premium</div><div style="font-size:20px;font-weight:800;color:#c9922a;">R${my.premium.toLocaleString()}</div><div style="font-size:10px;color:#6b7280;">#${myRankPrem} of ${n}</div></div>
  </div>`:'' ;
  const premRows=byPrem.map((a,i)=>{const isMe=a.code===currentUser.code;return`<tr style="${isMe?'background:#fdf6ed;':''}"><td style="padding:7px 8px;font-size:13px;text-align:center;">${medals[i]||i+1}</td><td style="padding:7px 8px;font-size:12px;font-weight:${isMe?700:500};color:#0d1f3c;">${a.name}${isMe?' ★':''}${_newBadge(a.code)}</td><td style="padding:7px 8px;font-size:12px;font-weight:700;color:#c9922a;">R${a.premium.toLocaleString()}</td></tr>`;}).join('');
  const caseRows=byCases.map((a,i)=>{const isMe=a.code===currentUser.code;return`<tr style="${isMe?'background:#fdf6ed;':''}"><td style="padding:7px 8px;font-size:13px;text-align:center;">${medals[i]||i+1}</td><td style="padding:7px 8px;font-size:12px;font-weight:${isMe?700:500};color:#0d1f3c;">${a.name}${isMe?' ★':''}${_newBadge(a.code)}</td><td style="padding:7px 8px;font-size:12px;font-weight:700;color:#0d1f3c;">${a.cases}</td></tr>`;}).join('');
  el.innerHTML=`<div style="font-size:11px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;">📅 ${yr} Year-to-Date</div>`+myCard+
    `<div class="team-stats-card" style="margin-bottom:8px;"><div class="team-stats-hd" style="padding:10px 12px;"><div style="color:#f5d98b;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:1px;">💰 ${yr} YTD</div><div style="color:#fff;font-size:13px;font-weight:700;">Most Premiums</div></div><div style="overflow-x:auto;"><table class="team-stats-tbl"><thead><tr><th>#</th><th>Advisor</th><th>Premium</th></tr></thead><tbody>${premRows}</tbody></table></div></div>`+
    `<div class="team-stats-card"><div class="team-stats-hd" style="padding:10px 12px;"><div style="color:#f5d98b;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:1px;">📋 ${yr} YTD</div><div style="color:#fff;font-size:13px;font-weight:700;">Most Cases</div></div><div style="overflow-x:auto;"><table class="team-stats-tbl"><thead><tr><th>#</th><th>Advisor</th><th>Cases</th></tr></thead><tbody>${caseRows}</tbody></table></div></div>`;
  renderYTDTop3();
}
function renderYTDTop3(){
  const hubEl=document.getElementById('hubYTDTop3');
  const opsEl=document.getElementById('opsYTDTop3');
  const els=[hubEl,opsEl].filter(Boolean);
  if(!els.length)return;
  // Sync user photos from Firebase then render
  if(window.FB_READY&&window.FB.getAllUsers){
    window.FB.getAllUsers().then(fbUsers=>{
      if(fbUsers&&Object.keys(fbUsers).length){const local=getUsers();Object.assign(local,fbUsers);saveUsers(local);}
      _renderYTDTop3Inner(els);
    }).catch(()=>_renderYTDTop3Inner(els));
  } else {
    _renderYTDTop3Inner(els);
  }
}
function _renderYTDTop3Inner(els){
  const stats=getYTDStats();
  const yr=new Date().getFullYear();
  if(!stats.length){
    const isOps=currentUser&&(currentUser.isManager||currentUser.isOps);
    els.forEach(el=>el.innerHTML=isOps?`<div style="background:#f9f9f9;border:1px dashed #d1d5db;border-radius:12px;padding:12px 14px;text-align:center;color:#9ca3af;font-size:11px;margin-bottom:4px;">No YTD stats yet — add monthly stats via <b>Operations → Production Stats</b></div>`:'');
    return;
  }
  const sorted=[...stats].filter(s=>!REVOKED_CODES.has(s.code)).sort((a,b)=>b.premium-a.premium);
  const _ring={gold:'border:3px solid #f59e0b;box-shadow:0 0 0 2px #fef9c3,0 0 10px rgba(245,158,11,0.45);',silver:'border:3px solid #9ca3af;box-shadow:0 0 0 2px #f1f5f9,0 0 10px rgba(156,163,175,0.4);',bronze:'border:3px solid #cd7f32;box-shadow:0 0 0 2px #fff7ed,0 0 10px rgba(180,83,9,0.35);'};
  const _bg={gold:'background:#fef3c7;',silver:'background:#f3f4f6;',bronze:'background:#ffedd5;'};
  const _badgeCol={gold:'#f59e0b',silver:'#9ca3af',bronze:'#cd7f32'};
  const _cls=['gold','silver','bronze'];
  const _medals=['🥇','🥈','🥉'];
  const _ytdUsers=getUsers();
  const _card=(r,rank)=>{
    if(!r)return`<div class="podium-col"></div>`;
    const cls=_cls[rank-1],medal=_medals[rank-1];
    const firstName=r.name.split(' ')[0];
    const photo=_ytdUsers[r.code]?.photo||null;
    return`<div class="podium-col"><div class="top3-card ${cls}">
      <div style="position:relative;width:52px;margin:0 auto 6px;">
        ${photo
          ?`<img src="${photo}" style="width:52px;height:52px;border-radius:50%;object-fit:cover;display:block;${_ring[cls]}">`
          :`<div style="width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:26px;${_bg[cls]}${_ring[cls]}">${medal}</div>`
        }
        <div style="position:absolute;bottom:-1px;right:-1px;width:18px;height:18px;border-radius:50%;background:${_badgeCol[cls]};color:#fff;font-size:9px;font-weight:900;display:flex;align-items:center;justify-content:center;border:1.5px solid #fff;">${rank}</div>
      </div>
      <div class="top3-name">${firstName}${_newBadge(r.code)}</div>
      <div class="top3-metrics"><span>R${r.premium.toLocaleString()}</span><span>${r.cases} cases</span></div>
    </div></div>`;
  };
  const html=`<div class="full-card" style="margin-bottom:12px;padding:14px 0 0;overflow:hidden;">
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:12px;padding:0 14px;">
      <div style="width:3px;height:14px;background:#c9922a;border-radius:2px;"></div>
      <div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:1px;">📅 ${yr} Year-to-Date Leaders</div>
    </div>
    <div class="podium-wrap">
      ${_card(sorted[1],2)}
      ${_card(sorted[0],1)}
      ${_card(sorted[2],3)}
    </div>
  </div>`;
  els.forEach(el=>el.innerHTML=html);
}
// ── END PRODUCTION STATS ──────────────────────────────────────────────
// ── INBOX & CHAT ─────────────────────────────────────────────────────────
let _inboxUnsub=null, _sentUnsub=null, _chatListUnsub=null, _chatThreadUnsub=null;
let _sentMsgs=[];
let _currentChatId=null, _currentChatPartner=null;
const CHAT_COLORS=['#0d1f3c','#1b4f8a','#c9922a','#059669','#7c3aed','#be185d','#0891b2','#dc2626'];
function chatColor(code){let h=0;for(let i=0;i<code.length;i++)h=(h*31+code.charCodeAt(i))%CHAT_COLORS.length;return CHAT_COLORS[h];}

function startInboxListener(){
  if(!window.FB_READY||!currentUser)return;
  if(_inboxUnsub)_inboxUnsub();
  _inboxUnsub=window.FB.onInbox(currentUser.code,msgs=>{
    window._inboxMsgs=msgs;
    renderInboxList();
    updateInboxBadge();
    updateChatBadge();
  });
}
function startSentListener(){
  if(!window.FB_READY||!currentUser)return;
  if(_sentUnsub)_sentUnsub();
  _sentUnsub=window.FB.onSentInbox(currentUser.code,msgs=>{
    _sentMsgs=msgs;
    renderSentList();
  });
}
function codeToName(code){
  if(code==='PURSHIVILLE')return'Purshiville Nortje (Manager)';
  if(code==='ARLENE')return'Arlene (Ops)';
  if(code==='ALL')return'All Team';
  const u=ADVISOR_LIST.find(a=>a.code===code);
  return u?u.name:code;
}
function renderSentList(){
  const el=document.getElementById('sentList');if(!el||!currentUser)return;
  if(!_sentMsgs.length){el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:24px 16px;">No sent messages yet.</div>';return;}
  const typeIcon={notice:'📢',stats:'📊',message:'✉️',chat:'💬',reminder:'🗓️'};
  el.innerHTML=_sentMsgs.map(m=>{
    const ts=m.sentAt?.toDate?m.sentAt.toDate():m.sentAt?new Date(m.sentAt):new Date();
    const timeStr=ts.toLocaleDateString('en-ZA',{day:'numeric',month:'short'})+' '+ts.toLocaleTimeString('en-ZA',{hour:'2-digit',minute:'2-digit'});
    const recipient=m.to==='ALL'?null:m.to;
    const isRead=recipient&&(m.readBy||[]).includes(recipient);
    const tick=m.from==='SYSTEM'?'':isRead
      ?'<span class="inbox-tick read" title="Read">✓✓</span>'
      :'<span class="inbox-tick delivered" title="Delivered">✓</span>';
    return`<div class="inbox-item" style="cursor:default;">
      <div class="inbox-icon ${m.type||'message'}">${typeIcon[m.type||'message']||'📌'}</div>
      <div class="inbox-meta">
        <div class="inbox-title">To: ${codeToName(m.to)}</div>
        ${m.title?`<div class="inbox-body" style="font-weight:600;color:#374151;">${m.title}</div>`:''}
        ${m.body?`<div class="inbox-body">${m.body}</div>`:''}
        <div class="inbox-time">${timeStr}</div>
      </div>
      ${tick}
    </div>`;
  }).join('');
}
function switchInboxTab(tab){
  const received=tab==='received';
  document.getElementById('inboxList').style.display=received?'':'none';
  document.getElementById('sentList').style.display=received?'none':'';
  document.getElementById('inboxTabReceived').classList.toggle('active',received);
  document.getElementById('inboxTabSent').classList.toggle('active',!received);
}
function startChatListListener(){
  if(!window.FB_READY||!currentUser)return;
  if(_chatListUnsub)_chatListUnsub();
  _chatListUnsub=window.FB.onChats(currentUser.code,chats=>{
    window._myChats=chats;
    updateChatBadge();
    if(!_currentChatId) renderChatContacts();
  });
}
function updateInboxBadge(){
  const msgs=window._inboxMsgs||[];
  // Bell: notices, stats, reminders — everything except direct messages and chats
  const unread=msgs.filter(m=>!(m.readBy||[]).includes(currentUser.code)&&m.type!=='message'&&m.type!=='chat').length;
  const badge=document.getElementById('inboxBadge');
  if(!badge)return;
  if(unread>0){badge.style.display='flex';badge.textContent=unread>99?'99+':unread;}
  else badge.style.display='none';
}
function updateChatBadge(){
  // Envelope: unread chat conversations + unread direct inbox messages
  const chats=window._myChats||[];
  let unread=0;
  chats.forEach(c=>{if((c.unread||{})[currentUser.code]>0)unread++;});
  const msgs=window._inboxMsgs||[];
  unread+=msgs.filter(m=>!(m.readBy||[]).includes(currentUser.code)&&(m.type==='message'||m.type==='chat')).length;
  const badge=document.getElementById('chatBadge');
  if(!badge)return;
  if(unread>0){badge.style.display='flex';badge.textContent=unread>99?'99+':unread;}
  else badge.style.display='none';
}

function openInboxPanel(){
  document.getElementById('inboxPanel').classList.add('open');
  document.getElementById('inboxOverlay').style.display='block';
  switchInboxTab('received');
  renderInboxList();
  // Refresh user photos from Firebase so avatars are up to date
  if(window.FB_READY){window.FB.getAllUsers().then(fbUsers=>{if(fbUsers&&Object.keys(fbUsers).length){const local=getUsers();Object.assign(local,fbUsers);saveUsers(local);renderInboxList();}}).catch(()=>{});}
  if(currentUser.isManager||currentUser.isOps){
    document.getElementById('inboxCompose').style.display='block';
    const sel=document.getElementById('inboxComposeTo');
    const recipients=[...ADVISOR_LIST];
    if(currentUser.isOps&&!currentUser.isManager)recipients.push({code:'PURSHIVILLE',name:'Purshiville Nortje (Manager)'});
    recipients.sort((a,b)=>a.name.localeCompare(b.name));
    sel.innerHTML='<option value="">— Select recipient —</option>'+
      recipients.map(a=>`<option value="${a.code}">${a.name}</option>`).join('');
  } else {
    document.getElementById('inboxAdvisorCompose').style.display='block';
    // Populate recipients: all other advisors + manager + Arlene
    const advSel=document.getElementById('inboxAdvisorComposeTo');
    if(advSel){
      const recipients=[
        ...ADVISOR_LIST.filter(a=>a.code!==currentUser.code),
        {code:'PURSHIVILLE',name:'Purshiville Nortje (Manager)'},
        {code:'ARLENE',name:'Arlene (Ops)'}
      ].sort((a,b)=>a.name.localeCompare(b.name));
      advSel.innerHTML=recipients.map(r=>`<option value="${r.code}">${r.name}</option>`).join('');
    }
  }
}
function closeInboxPanel(){
  document.getElementById('inboxPanel').classList.remove('open');
  document.getElementById('inboxOverlay').style.display='none';
}
function renderInboxList(){
  const el=document.getElementById('inboxList');
  if(!el||!currentUser)return;
  const msgs=[...(window._inboxMsgs||[])].sort((a,b)=>{
    const aRead=(a.readBy||[]).includes(currentUser.code);
    const bRead=(b.readBy||[]).includes(currentUser.code);
    if(aRead!==bRead)return aRead?1:-1; // unread first
    const aT=a.sentAt?.toDate?a.sentAt.toDate():a.sentAt?new Date(a.sentAt):0;
    const bT=b.sentAt?.toDate?b.sentAt.toDate():b.sentAt?new Date(b.sentAt):0;
    return bT-aT; // newest first within each group
  });
  if(!msgs.length){el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:24px 16px;">No notifications yet.</div>';return;}
  const typeIcon={notice:'📢',stats:'📊',message:'✉️',chat:'💬',reminder:'🗓️'};
  const _allUsers=getUsers();
  el.innerHTML=msgs.map(m=>{
    const unread=!(m.readBy||[]).includes(currentUser.code);
    const ts=m.sentAt?.toDate?m.sentAt.toDate():m.sentAt?new Date(m.sentAt):new Date();
    const timeStr=ts.toLocaleDateString('en-ZA',{day:'numeric',month:'short'})+' '+ts.toLocaleTimeString('en-ZA',{hour:'2-digit',minute:'2-digit'});
    const chatFrom=m.chatFrom||'';
    const chatFromName=(m.chatFromName||'').replace(/'/g,'&#39;');
    const senderPhoto=_allUsers[m.from]?.photo||null;
    const senderInitial=(m.fromName||'?').charAt(0).toUpperCase();
    const isSystem=!m.from||m.from==='SYSTEM';
    const avatarHtml=senderPhoto
      ?`<img src="${senderPhoto}" style="width:36px;height:36px;border-radius:50%;object-fit:cover;flex-shrink:0;">`
      :isSystem
        ?`<div class="inbox-icon ${m.type||'message'}">${typeIcon[m.type||'message']||'📌'}</div>`
        :`<div style="width:36px;height:36px;border-radius:50%;background:${chatColor(m.from||'X')};color:#fff;font-size:15px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${senderInitial}</div>`;
    return`<div class="inbox-item${unread?' unread':''}${chatFrom?' chat-tap':''}" onclick="readInboxItem('${m.id}',this,'${chatFrom}','${chatFromName}')" style="${chatFrom?'cursor:pointer;':''}" title="${chatFrom?'Tap to open conversation':''}">
      ${avatarHtml}
      <div class="inbox-meta">
        <div class="inbox-title">${m.title||'Notification'}${chatFrom?' <span style="font-size:9px;color:#7c3aed;font-weight:700;margin-left:4px;">TAP TO REPLY</span>':''}</div>
        ${m.body?`<div class="inbox-body">${m.body}</div>`:''}
        <div class="inbox-time">${m.fromName||'System'} · ${timeStr}</div>
      </div>
      ${unread?'<div class="inbox-unread-dot"></div>':''}
    </div>`;
  }).join('');
}
function readInboxItem(id,el,chatFrom,chatFromName){
  if(el.classList.contains('unread')){
    el.classList.remove('unread');
    el.querySelector('.inbox-unread-dot')?.remove();
    if(window.FB_READY)window.FB.markInboxRead(id,currentUser.code).catch(()=>{});
    updateInboxBadge();
  }
  if(chatFrom&&chatFromName){
    closeInboxPanel();
    openChatPanel();
    openChatThread(chatFrom,chatFromName);
  }
}
async function sendManagerInboxMessage(){
  const to=document.getElementById('inboxComposeTo').value;
  const title=document.getElementById('inboxComposeTitle').value.trim();
  const body=document.getElementById('inboxComposeBody').value.trim();
  if(!to)return alert('Please select an advisor.');
  if(!title)return alert('Please enter a subject.');
  if(!window.FB_READY)return alert('Firebase not connected.');
  const advisorName=ADVISOR_LIST.find(a=>a.code===to)?.name||to;
  await window.FB.sendInbox({to,from:currentUser.code,fromName:currentUser.name,title,body,type:'message'});
  document.getElementById('inboxComposeTitle').value='';
  document.getElementById('inboxComposeBody').value='';
  document.getElementById('inboxComposeTo').value='';
  alert(`Message sent to ${advisorName}.`);
}

async function sendAdvisorInboxMessage(){
  const to=document.getElementById('inboxAdvisorComposeTo').value;
  const title=document.getElementById('inboxAdvisorComposeTitle').value.trim();
  const body=document.getElementById('inboxAdvisorComposeBody').value.trim();
  if(!title)return alert('Please enter a subject.');
  if(!window.FB_READY)return alert('Firebase not connected.');
  await window.FB.sendInbox({to,from:currentUser.code,fromName:currentUser.name,title,body,type:'message'});
  document.getElementById('inboxAdvisorComposeTitle').value='';
  document.getElementById('inboxAdvisorComposeBody').value='';
  const toName=to==='ARLENE'?'Arlene':'Purshiville Nortje';
  alert(`Message sent to ${toName}.`);
}

// ── CHAT ──────────────────────────────────────────────────────────────────
function openChatPanel(){
  document.getElementById('chatPanel').classList.add('open');
  document.getElementById('chatOverlay').style.display='block';
  _currentChatId=null;_currentChatPartner=null;
  renderChatContacts();
  // Refresh user photos from Firebase so avatars are up to date
  if(window.FB_READY){window.FB.getAllUsers().then(fbUsers=>{if(fbUsers&&Object.keys(fbUsers).length){const local=getUsers();Object.assign(local,fbUsers);saveUsers(local);renderChatContacts();}}).catch(()=>{});}
}
function closeChatPanel(){
  document.getElementById('chatPanel').classList.remove('open');
  document.getElementById('chatOverlay').style.display='none';
  if(_chatThreadUnsub){_chatThreadUnsub();_chatThreadUnsub=null;}
  _currentChatId=null;_currentChatPartner=null;
}
function getChatId(codeA,codeB){return [codeA,codeB].sort().join('__');}
function renderChatContacts(){
  const el=document.getElementById('chatBody');
  if(!el||!currentUser)return;
  const chats=window._myChats||[];
  const chatMap={};chats.forEach(c=>chatMap[c.id]=c);
  // Build contact list from ADVISOR_LIST + manager, excluding self
  const contacts=[];
  ADVISOR_LIST.forEach(a=>{if(a.code!==currentUser.code)contacts.push(a);});
  if(!currentUser.isManager&&!currentUser.isOps){
    contacts.push({code:'PURSHIVILLE',name:'Purshiville Nortje (Manager)'});
    contacts.push({code:'ARLENE',name:'Arlene (Ops)'});
  }
  contacts.sort((a,b)=>a.name.localeCompare(b.name));
  if(!contacts.length){el.innerHTML='<div style="padding:16px;color:#9ca3af;font-size:13px;text-align:center;">No contacts available.</div>';return;}
  const _chatUsers=getUsers();
  el.innerHTML=contacts.map(c=>{
    const chatId=getChatId(currentUser.code,c.code);
    const chatData=chatMap[chatId];
    const unread=chatData?(chatData.unread||{})[currentUser.code]||0:0;
    const lastMsg=chatData?.lastMessage||'Start a conversation';
    const contactPhoto=_chatUsers[c.code]?.photo||null;
    const contactAvatar=contactPhoto
      ?`<img src="${contactPhoto}" style="width:38px;height:38px;border-radius:50%;object-fit:cover;flex-shrink:0;">`
      :`<div class="chat-av" style="background:${chatColor(c.code)};">${c.name.charAt(0)}</div>`;
    return`<div class="chat-contact" onclick="openChatThread('${c.code}','${c.name.replace(/'/g,'&#39;')}')">
      ${contactAvatar}
      <div style="flex:1;min-width:0;">
        <div class="chat-contact-name">${c.name}</div>
        <div class="chat-contact-last">${lastMsg}</div>
      </div>
      ${unread?`<div class="chat-unread-badge">${unread}</div>`:''}
    </div>`;
  }).join('');
}
function openChatThread(partnerCode,partnerName){
  _currentChatPartner={code:partnerCode,name:partnerName};
  _currentChatId=getChatId(currentUser.code,partnerCode);
  const el=document.getElementById('chatBody');
  const _partnerPhoto=getUsers()[partnerCode]?.photo||null;
  const _partnerAvatar=_partnerPhoto
    ?`<img src="${_partnerPhoto}" style="width:30px;height:30px;border-radius:50%;object-fit:cover;flex-shrink:0;">`
    :`<div class="chat-av" style="background:${chatColor(partnerCode)};width:30px;height:30px;font-size:12px;">${partnerName.charAt(0)}</div>`;
  el.innerHTML=`<div class="chat-thread">
    <div class="chat-thread-hd">
      <button class="chat-back" onclick="backToChatContacts()">‹</button>
      ${_partnerAvatar}
      <div class="chat-thread-name">${partnerName}</div>
    </div>
    <div class="chat-messages" id="chatThreadMessages"></div>
    <div class="chat-input-row" style="position:relative;">
      <div style="position:relative;flex-shrink:0;">
        <button onclick="toggleChatEmoji(event)" style="background:none;border:none;font-size:20px;cursor:pointer;padding:4px 6px;line-height:1;">😊</button>
        <div id="chatEmojiPicker" style="display:none;position:absolute;bottom:44px;left:0;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:8px;box-shadow:0 4px 16px rgba(0,0,0,.15);z-index:999;width:220px;flex-wrap:wrap;gap:4px;"></div>
      </div>
      <input class="chat-input" id="chatThreadInput" placeholder="Type a message…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendChatMsg();}"/>
      <button class="chat-send-btn" onclick="sendChatMsg()">➤</button>
    </div>
  </div>`;
  if(_chatThreadUnsub){_chatThreadUnsub();_chatThreadUnsub=null;}
  if(window.FB_READY){
    _chatThreadUnsub=window.FB.onMessages(_currentChatId,msgs=>{
      renderChatMessages(msgs);
      // Mark received messages as read
      msgs.forEach(m=>{if(m.from!==currentUser.code&&!(m.readBy||[]).includes(currentUser.code)){window.FB.markMessageRead(m.id,currentUser.code).catch(()=>{});}});
      // Clear unread count on this chat
      window.FB.clearChatUnread(_currentChatId,currentUser.code).catch(()=>{});
    });
  }
}
function backToChatContacts(){
  if(_chatThreadUnsub){_chatThreadUnsub();_chatThreadUnsub=null;}
  _currentChatId=null;_currentChatPartner=null;
  renderChatContacts();
}
function renderChatMessages(msgs){
  const el=document.getElementById('chatThreadMessages');
  if(!el)return;
  if(!msgs.length){el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:12px;padding:16px;">No messages yet. Say hello!</div>';return;}
  const _msgUsers=getUsers();
  el.innerHTML=msgs.map(m=>{
    const mine=m.from===currentUser.code;
    const ts=m.sentAt?.toDate?m.sentAt.toDate():new Date();
    const timeStr=ts.toLocaleTimeString('en-ZA',{hour:'2-digit',minute:'2-digit'});
    const senderPhoto=!mine?(_msgUsers[m.from]?.photo||null):null;
    const senderInitialChat=(m.fromName||'?').charAt(0).toUpperCase();
    const senderAvatar=!mine
      ?senderPhoto
        ?`<img src="${senderPhoto}" style="width:26px;height:26px;border-radius:50%;object-fit:cover;flex-shrink:0;margin-right:6px;align-self:flex-end;">`
        :`<div style="width:26px;height:26px;border-radius:50%;background:${chatColor(m.from||'X')};color:#fff;font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-right:6px;align-self:flex-end;">${senderInitialChat}</div>`
      :'';
    return`<div class="chat-bubble-wrap ${mine?'mine':'theirs'}" style="margin-bottom:8px;">
      ${!mine?senderAvatar:''}
      <div style="max-width:75%;">
        ${!mine?`<div style="font-size:10px;color:#6b7280;margin-bottom:2px;padding:0 2px;">${m.fromName}</div>`:''}
        <div class="chat-bubble ${mine?'mine':'theirs'}">${m.text}</div>
        <div class="chat-bubble-time">${timeStr}</div>
      </div>
    </div>`;
  }).join('');
  el.scrollTop=el.scrollHeight;
}
async function sendChatMsg(){
  const input=document.getElementById('chatThreadInput');
  if(!input||!_currentChatId||!_currentChatPartner)return;
  const text=input.value.trim();
  if(!text)return;
  input.value='';
  if(!window.FB_READY)return;
  const participants=[currentUser.code,_currentChatPartner.code];
  try{
    await window.FB.sendChatMessage(_currentChatId,participants,{from:currentUser.code,fromName:currentUser.name,text});
    // Also push an inbox notification to the partner so it appears in their notification bell
    await window.FB.sendInbox({
      to:_currentChatPartner.code,
      from:currentUser.code,
      fromName:currentUser.name,
      title:`New message from ${currentUser.name}`,
      body:text.length>100?text.slice(0,97)+'…':text,
      type:'chat',
      chatFrom:currentUser.code,
      chatFromName:currentUser.name
    });
  }catch(e){console.warn(e);}
}
const _CHAT_EMOJIS='😊 😂 😍 🥰 😎 🤩 😅 😢 😭 😠 🤔 🙏 👍 👎 👋 🤝 💪 🙌 👏 ✅ ❌ ⚠️ 🔥 💯 🎉 🎊 🏆 🌟 💡 📞 📱 💼 📋 📊 💰 ⏰ 🗓️ 📌 🚀 👀 💬 ✍️ 📝 🤦 🤷 😴 🥳 🤗 💃 🕺'.split(' ');
function toggleChatEmoji(e){
  e.stopPropagation();
  const p=document.getElementById('chatEmojiPicker');if(!p)return;
  if(p.style.display==='flex'){p.style.display='none';return;}
  if(!p.dataset.built){
    p.dataset.built='1';
    p.innerHTML=_CHAT_EMOJIS.map(em=>`<button onclick="insertChatEmoji('${em}')" style="background:none;border:none;font-size:20px;cursor:pointer;padding:3px;border-radius:6px;line-height:1;" onmouseover="this.style.background='#f3f4f6'" onmouseout="this.style.background='none'">${em}</button>`).join('');
  }
  p.style.display='flex';
  setTimeout(()=>document.addEventListener('click',function h(ev){if(!p.contains(ev.target)){p.style.display='none';document.removeEventListener('click',h);}},{once:false}),0);
}
function insertChatEmoji(em){
  const inp=document.getElementById('chatThreadInput');if(!inp)return;
  const s=inp.selectionStart??inp.value.length,en=inp.selectionEnd??inp.value.length;
  inp.value=inp.value.slice(0,s)+em+inp.value.slice(en);
  const np=s+em.length;inp.focus();inp.setSelectionRange(np,np);
  const p=document.getElementById('chatEmojiPicker');if(p)p.style.display='none';
}
// Chat broadcast (manager only)
function chatOpenBroadcast(){
  document.getElementById('chatBroadcastBar').style.display='block';
  document.getElementById('chatBroadcastMsg').focus();
}
function chatCloseBroadcast(){
  document.getElementById('chatBroadcastBar').style.display='none';
  document.getElementById('chatBroadcastMsg').value='';
}
async function chatSendBroadcast(){
  const text=document.getElementById('chatBroadcastMsg').value.trim();
  if(!text)return;
  if(!window.FB_READY)return showAlert('Firebase not connected.','error');
  const recipients=[...ADVISOR_LIST];
  let sent=0;
  for(const advisor of recipients){
    const chatId=getChatId(currentUser.code,advisor.code);
    const participants=[currentUser.code,advisor.code];
    try{
      await window.FB.sendChatMessage(chatId,participants,{from:currentUser.code,fromName:currentUser.name,text});
      await window.FB.sendInbox({to:advisor.code,from:currentUser.code,fromName:currentUser.name,title:`📢 Broadcast from ${currentUser.name}`,body:text,type:'chat',chatFrom:currentUser.code,chatFromName:currentUser.name});
      sent++;
    }catch(e){console.warn(e);}
  }
  chatCloseBroadcast();
  showAlert(`Broadcast sent to ${sent} advisors.`,'success');
}
// ── END INBOX & CHAT ──────────────────────────────────────────────────────
// ── LOA CLIENT SESSION ────────────────────────────────────────────────────
let _loaClient=(()=>{try{return JSON.parse(sessionStorage.getItem('tl_loa_client')||'null')||{name:'',idNumber:''};}catch(e){return{name:'',idNumber:''};} })();
window._loaFile=null;
function saveLoaClient(name,idNumber){_loaClient={name,idNumber};try{sessionStorage.setItem('tl_loa_client',JSON.stringify(_loaClient));}catch(e){}}

function showClientDetailStep(email,ccList){
  window._loaEmail=email; window._loaCC=ccList||[];
  let ov=document.getElementById('loaClientOverlay'); if(ov)ov.remove();
  ov=document.createElement('div');
  ov.id='loaClientOverlay';
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9200;display:flex;align-items:center;justify-content:center;';
  const fileLabel=window._loaFile
    ?`<span style="color:#059669;font-weight:700;">✅ ${window._loaFile.name}</span>`
    :`<span style="color:#6b7280;">📎 Tap to upload LOA</span>`;
  const fileNote=window._loaFile
    ?`<div style="font-size:10px;color:#059669;margin-top:3px;">Will download automatically when Gmail opens — attach from Downloads.</div>`
    :`<div style="font-size:10px;color:#9ca3af;margin-top:3px;">Downloads to your device when Gmail opens so you can attach it.</div>`;
  ov.innerHTML=`<div style="background:#fff;border-radius:16px;padding:22px 20px 18px;width:320px;max-width:94vw;box-shadow:0 8px 32px rgba(0,0,0,.25);max-height:92vh;overflow-y:auto;">
    <h3 style="margin:0 0 4px;font-size:15px;font-weight:700;color:#0d1f3c;text-align:center;">📋 Client Details</h3>
    <p style="margin:0 0 14px;font-size:12px;color:#6b7280;text-align:center;">Upload the LOA — name &amp; ID are read automatically.</p>
    <div style="display:flex;flex-direction:column;gap:10px;margin-bottom:16px;">
      <div>
        <label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">Client Full Name</label>
        <input id="loaClientName" placeholder="e.g. Zanele Dlamini" value="${(_loaClient.name||'').replace(/"/g,'&quot;')}" style="width:100%;padding:8px 10px;font-size:13px;border:1px solid #e5e7eb;border-radius:8px;background:#f9f9f9;box-sizing:border-box;"/>
      </div>
      <div>
        <label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">ID Number <span style="color:#dc2626;">★</span></label>
        <input id="loaIdInput" placeholder="13-digit ID number" value="${(_loaClient.idNumber||'').replace(/"/g,'&quot;')}" maxlength="13" inputmode="numeric" style="width:100%;padding:8px 10px;font-size:14px;border:1px solid #e5e7eb;border-radius:8px;background:#f9f9f9;box-sizing:border-box;font-family:monospace;letter-spacing:1px;" oninput="loaIdCheck()"/>
        <div id="loaIdNote" style="font-size:10px;color:#9ca3af;margin-top:3px;">Required — always used in the subject line.</div>
      </div>
      <div>
        <label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">LOA Document <span style="color:#9ca3af;font-weight:400;">(optional)</span></label>
        <input type="file" id="loaFileInput" accept=".pdf,.jpg,.jpeg,.png,.heic,.heif,image/*" style="display:none;" onchange="loaFileSelected(this)"/>
        <input type="file" id="loaCamInput" accept="image/*" capture="environment" style="display:none;" onchange="loaFileSelected(this)"/>
        <div style="display:flex;gap:6px;">
          <button onclick="document.getElementById('loaFileInput').click()" id="loaFileBtn" style="flex:1;padding:9px 10px;background:#f4f2ed;border:1.5px dashed #d1d5db;border-radius:8px;font-size:12px;font-weight:600;color:#374151;cursor:pointer;text-align:left;box-sizing:border-box;">${fileLabel}</button>
          <button onclick="document.getElementById('loaCamInput').click()" title="Take photo or scan" style="padding:9px 11px;background:#f4f2ed;border:1.5px dashed #d1d5db;border-radius:8px;font-size:18px;cursor:pointer;flex-shrink:0;">📷</button>
        </div>
        <div id="loaFileNote">${fileNote}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px;">
      <button onclick="document.getElementById('loaClientOverlay').remove()" style="flex:1;padding:9px;background:#f4f2ed;color:#374151;border:none;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer;">Cancel</button>
      <button id="loaNextBtn" onclick="loaClientNext()" style="flex:2;padding:9px;background:#0d1f3c;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;opacity:.45;pointer-events:none;">Next →</button>
    </div>
  </div>`;
  ov.addEventListener('click',e=>{if(e.target===ov)ov.remove();});
  document.body.appendChild(ov);
  setTimeout(()=>{ loaIdCheck(); if(!_loaClient.idNumber)document.getElementById('loaIdInput')?.focus(); else document.getElementById('loaClientName')?.focus(); },50);
}
function _loadPdfJs(){
  return new Promise((res,rej)=>{
    if(window.pdfjsLib){res();return;}
    const s=document.createElement('script');
    s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
    s.onload=()=>{window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';res();};
    s.onerror=rej; document.head.appendChild(s);
  });
}
async function _extractTextFromPDF(file){
  await _loadPdfJs();
  const buf=await file.arrayBuffer();
  const pdf=await window.pdfjsLib.getDocument({data:buf}).promise;
  let text='';
  for(let i=1;i<=Math.min(pdf.numPages,3);i++){
    const pg=await pdf.getPage(i);
    const ct=await pg.getTextContent();
    text+=ct.items.map(x=>x.str).join(' ')+'\n';
  }
  return text;
}
function _parseLoaDetails(text){
  const idMatch=text.match(/\b(\d{13})\b/);
  const idNumber=idMatch?idMatch[1]:'';
  let name='';
  const patterns=[
    /(?:full\s+name|client(?:'s)?\s+name|name\s+of\s+(?:client|policyholder)|policyholder)[:\s,]+([A-Z][A-Za-z'-]+(?:\s+[A-Z][A-Za-z'-]+){1,5})/i,
    /I[,\s]+([A-Z][A-Za-z'-]+(?:\s+[A-Z][A-Za-z'-]+){1,5})[,\s]+(?:hereby|the undersigned|ID\s*[Nn]o)/i,
    /(?:name\s*[:\/])\s*([A-Z][A-Za-z'-]+(?:\s+[A-Z][A-Za-z'-]+){1,5})/i,
  ];
  for(const p of patterns){const m=text.match(p);if(m){name=m[1].trim();break;}}
  return{name,idNumber};
}
async function _ocrImage(file){
  if(!window.Tesseract){
    await new Promise((res,rej)=>{
      const s=document.createElement('script');
      s.src='https://cdn.jsdelivr.net/npm/tesseract.js@4/dist/tesseract.min.js';
      s.onload=res; s.onerror=rej; document.head.appendChild(s);
    });
  }
  const worker=await Tesseract.createWorker('eng',1,{
    workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@4/dist/worker.min.js',
    corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@4/tesseract-core-simd.wasm.js',
    langPath:'https://tessdata.projectnaptha.com/4.0.0',
  });
  try{
    const{data:{text}}=await worker.recognize(file);
    return text;
  }finally{await worker.terminate();}
}
async function loaFileSelected(input){
  if(!input.files||!input.files[0])return;
  window._loaFile=input.files[0];
  const btn=document.getElementById('loaFileBtn');
  const note=document.getElementById('loaFileNote');
  if(note)note.innerHTML=`<div style="font-size:10px;color:#059669;margin-top:3px;">Will download automatically when Gmail opens — attach from Downloads.</div>`;
  const fname=window._loaFile.name.toLowerCase();
  const isPdf=fname.endsWith('.pdf');
  const isImg=/\.(jpe?g|png|heic|heif|webp|bmp)$/.test(fname);
  if(isPdf||isImg){
    if(btn)btn.innerHTML=`<span style="color:#6b7280;font-weight:600;">${isPdf?'⏳ Reading LOA…':'📷 Scanning — may take ~10 sec…'}</span>`;
    try{
      const text=isPdf?await _extractTextFromPDF(window._loaFile):await _ocrImage(window._loaFile);
      const{name,idNumber}=_parseLoaDetails(text);
      if(name){const f=document.getElementById('loaClientName');if(f)f.value=name;}
      if(idNumber){const f=document.getElementById('loaIdInput');if(f){f.value=idNumber;loaIdCheck();}}
    }catch(e){console.warn('LOA extract failed:',e);}
  }
  if(btn)btn.innerHTML=`<span style="color:#059669;font-weight:700;">✅ ${window._loaFile.name}</span>`;
}
function loaIdCheck(){
  const val=(document.getElementById('loaIdInput')?.value||'').trim();
  const btn=document.getElementById('loaNextBtn');
  const note=document.getElementById('loaIdNote');
  if(!btn)return;
  const ok=val.length>=6;
  btn.style.opacity=ok?'1':'.45'; btn.style.pointerEvents=ok?'auto':'none';
  if(note)note.style.color=ok?'#9ca3af':'#dc2626';
}
function loaClientNext(){
  const name=(document.getElementById('loaClientName')?.value||'').trim();
  const idNumber=(document.getElementById('loaIdInput')?.value||'').trim();
  if(idNumber.length<6){const n=document.getElementById('loaIdNote');if(n)n.style.color='#dc2626';return;}
  saveLoaClient(name,idNumber);
  document.getElementById('loaClientOverlay')?.remove();
  showEmailTypePicker(window._loaEmail,window._loaCC);
}
function triggerLoaDownload(){
  if(!window._loaFile)return;
  try{
    const url=URL.createObjectURL(window._loaFile);
    const a=document.createElement('a');
    a.href=url; a.download=window._loaFile.name;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url),15000);
  }catch(e){console.warn('LOA download failed:',e);}
}
function showLoaReminder(){
  const ex=document.getElementById('loaReminderToast');if(ex)ex.remove();
  const hasFile=!!window._loaFile;
  const msg=hasFile
    ?`LOA is downloading — attach it from your Downloads in Gmail`
    :`Attach the LOA from your device before sending`;
  const t=document.createElement('div');
  t.id='loaReminderToast';
  t.style.cssText='position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:#0d1f3c;color:#fff;padding:12px 18px 12px 14px;border-radius:12px;font-size:13px;font-weight:600;z-index:9999;display:flex;align-items:center;gap:10px;box-shadow:0 4px 20px rgba(0,0,0,.35);max-width:320px;width:90%;';
  t.innerHTML=`<span style="font-size:20px;flex-shrink:0;">📎</span><span style="flex:1;line-height:1.4;">${msg}</span><button onclick="this.parentElement.remove()" style="background:none;border:none;color:rgba(255,255,255,.55);font-size:20px;cursor:pointer;padding:0;flex-shrink:0;line-height:1;">✕</button>`;
  document.body.appendChild(t);
  setTimeout(()=>{if(t.parentElement)t.remove();},9000);
}
