function openGmailCompose(email, ccList, type){
  let subject, body;
  if(type==='refund'){
    subject='[Client ID Number] — Premium Refund Request';
    body='Dear [Team/Contact Name],\n\nOn behalf of [Full Name], I am requesting a premium refund for policy number [Policy Number]. Please confirm once processed and the amount has been transferred.\n\nThank you,\n[Your Name]';
  } else {
    subject='[Client ID Number] — Policy Schedule Request';
    body='Good day,\n\nPlease find the attached Letter of Authority. Kindly provide the full policy contracts including full names, surnames, and dates of birth of all insured lives, for all active policies owned by the client.\n\nKind regards';
  }
  let url='https://mail.google.com/mail/?view=cm&to='+encodeURIComponent(email)+'&su='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
  if(ccList&&ccList.length) url+='&cc='+encodeURIComponent(ccList.join(','));
  window.open(url,'_blank');
}
function showEmailTypePicker(email, ccList){
  let overlay=document.getElementById('emailTypeOverlay');
  if(overlay) overlay.remove();
  overlay=document.createElement('div');
  overlay.id='emailTypeOverlay';
  overlay.innerHTML=`
    <div id="emailTypeModal">
      <h3>Choose email type</h3>
      <p>Select the template to pre-fill before opening Gmail.</p>
      <button class="email-type-btn" onclick="closeEmailPicker();showScheduleEmailBuilder()">
        <span class="etb-icon">📋</span>
        <span><div class="etb-label">Schedule Request</div><div class="etb-sub">Select companies & generate one email for all</div></span>
      </button>
      <button class="email-type-btn" onclick="closeEmailPicker();showRefundEmailBuilder()">
        <span class="etb-icon">💰</span>
        <span><div class="etb-label">Refund Request</div><div class="etb-sub">Select companies & generate one email for all</div></span>
      </button>
      <button id="emailTypeCancel" onclick="closeEmailPicker()">Cancel</button>
    </div>`;
  window._etPickerCC=ccList||[];
  overlay.addEventListener('click',e=>{if(e.target===overlay)closeEmailPicker();});
  document.body.appendChild(overlay);
}
function closeEmailPicker(){
  const o=document.getElementById('emailTypeOverlay');
  if(o)o.remove();
}

