        <div><label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">ID Number</label><input id="refundIdNumber" placeholder="13-digit ID" style="width:100%;padding:7px 9px;font-size:12px;border:1px solid #e5e7eb;border-radius:7px;background:#f9f9f9;box-sizing:border-box;font-family:monospace;"/></div>
