function resizeImageToBase64(file,size=80,quality=0.75){
  return new Promise(resolve=>{
    const img=new Image();
    const url=URL.createObjectURL(file);
    img.onload=()=>{
      const canvas=document.createElement('canvas');
      canvas.width=size;canvas.height=size;
      const ctx=canvas.getContext('2d');
      const min=Math.min(img.width,img.height);
      const sx=(img.width-min)/2,sy=(img.height-min)/2;
      ctx.drawImage(img,sx,sy,min,min,0,0,size,size);
      URL.revokeObjectURL(url);
      resolve(canvas.toDataURL('image/jpeg',quality));
    };
    img.onerror=()=>{URL.revokeObjectURL(url);resolve(null);};
    img.src=url;
  });
}
function previewRegPhoto(input){
  const file=input.files?.[0];if(!file)return;
  resizeImageToBase64(file,80,0.75).then(b64=>{
    if(!b64)return;
    const el=document.getElementById('regPhotoPreview');
    if(el)el.innerHTML=`<img src="${b64}" style="width:64px;height:64px;border-radius:50%;object-fit:cover;"/>`;
    input._b64=b64;
  });
}
function loadTop3ProfilePhoto(selectId,imgId,inputId){
  const code=document.getElementById(selectId)?.value;
  const imgEl=document.getElementById(imgId);
  const inp=document.getElementById(inputId);
  if(!code){
    if(imgEl)imgEl.innerHTML='📷';
    if(inp)inp._b64=null;
    return;
  }
  const photo=getUsers()[code]?.photo||null;
  if(imgEl)imgEl.innerHTML=photo?`<img src="${photo}" style="width:36px;height:36px;border-radius:50%;object-fit:cover;"/>`:'📷';
  if(inp)inp._b64=photo;
}
function previewTop3Photo(input,previewId){
  const file=input.files?.[0];if(!file)return;
  resizeImageToBase64(file).then(b64=>{
    if(!b64)return;
    const el=document.getElementById(previewId);
    if(el)el.innerHTML=`<img src="${b64}" style="width:36px;height:36px;border-radius:50%;object-fit:cover;"/>`;
    input._b64=b64;
  });
}
function getTop3Data(){try{return JSON.parse(localStorage.getItem('tl_top3')||'{}');}catch(e){return{};}}
function saveTop3Data(d){localStorage.setItem('tl_top3',JSON.stringify(d));}

function renderTop3(){
  const el=document.getElementById('hubTop3');if(!el)return;
  const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  const now=new Date();
  // Show previous month's winners (awards published after month end)
  const prevMonth=new Date(now.getFullYear(),now.getMonth()-1,1);
  const periodKey=prevMonth.getFullYear()+'-'+(''+(prevMonth.getMonth()+1)).padStart(2,'0');
  const currentKey=now.getFullYear()+'-'+(''+(now.getMonth()+1)).padStart(2,'0');
  const data=getTop3Data();
  const prevRec=data[periodKey];const curRec=data[currentKey];
  const record=(curRec&&curRec.first?curRec:null)||(prevRec&&prevRec.first?prevRec:null);
  if(!record){el.innerHTML='';return;}
  const usedKey=data[periodKey]?periodKey:currentKey;
  const [yr,mo]=usedKey.split('-');
  const label=MONTHS[parseInt(mo)-1]+' '+yr;
  const _ring={gold:'border:3px solid #f59e0b;box-shadow:0 0 0 2px #fef9c3,0 0 10px rgba(245,158,11,0.45);',silver:'border:3px solid #9ca3af;box-shadow:0 0 0 2px #f1f5f9,0 0 10px rgba(156,163,175,0.4);',bronze:'border:3px solid #cd7f32;box-shadow:0 0 0 2px #fff7ed,0 0 10px rgba(180,83,9,0.35);'};
  const _bg={gold:'background:#fef3c7;',silver:'background:#f3f4f6;',bronze:'background:#ffedd5;'};
  const _badgeCol={gold:'#f59e0b',silver:'#9ca3af',bronze:'#cd7f32'};
  const _regUsers=getUsers();
  const _card=(r,cls,medal,posLabel)=>(r&&REVOKED_CODES.has(r.code))?`<div class="podium-col"></div>`:r?`
    <div class="podium-col">
      <div class="top3-card ${cls}">
        <div style="position:relative;width:52px;margin:0 auto 6px;">
          ${(r.photo||_regUsers[r.code]?.photo)
            ?`<img src="${r.photo||_regUsers[r.code].photo}" style="width:52px;height:52px;border-radius:50%;object-fit:cover;display:block;${_ring[cls]}">`
            :`<div style="width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:26px;${_bg[cls]}${_ring[cls]}">${medal}</div>`
          }
          <div style="position:absolute;bottom:-1px;right:-1px;width:18px;height:18px;border-radius:50%;background:${_badgeCol[cls]};color:#fff;font-size:9px;font-weight:900;display:flex;align-items:center;justify-content:center;border:1.5px solid #fff;">${posLabel}</div>
        </div>
        <div class="top3-name">${r.name}${_newBadge(r.code)}</div>
        ${r.note?`<div style="font-size:10px;color:${cls==='gold'?'#92400e':'#6b7280'};margin-top:3px;">${r.note}</div>`:''}
        <div class="top3-metrics">${r.ntu4!=null?`<span>4M NTU ${r.ntu4}%</span>`:''}${r.ntu15!=null?`<span>15M NTU ${r.ntu15}%</span>`:''}${r.persistency!=null?`<span>Pers ${r.persistency}%</span>`:''}</div>
      </div>
    </div>`:`<div class="podium-col"></div>`;
  el.innerHTML=`
    <div class="full-card" style="margin-bottom:12px;padding:14px 0 0;overflow:hidden;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:12px;padding:0 14px;">
        <div style="width:3px;height:14px;background:#c9922a;border-radius:2px;"></div>
        <div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:1px;">🏆 Advisors of the Month — ${label}</div>
      </div>
      <div class="podium-wrap">
        ${_card(record.second,'silver','🥈','2')}
        ${_card(record.first, 'gold',  '🥇','1')}
        ${_card(record.third, 'bronze','🥉','3')}
      </div>
    </div>`;
}

function saveTop3Awards(){
  const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  const mo=document.getElementById('statsPeriodMonth')?.value||('0'+(new Date().getMonth()+1)).slice(-2);
  const yr=document.getElementById('statsPeriodYear')?.value||new Date().getFullYear();
  const periodKey=`${yr}-${mo}`;
  const advisors=getUsers();
  const getAdv=(code)=>{const u=advisors[code]||ADVISOR_LIST.find(a=>a.code===code)||{};return{code,name:u.name||code};};
  const f1=document.getElementById('top3_first')?.value;
  const f2=document.getElementById('top3_second')?.value;
  const f3=document.getElementById('top3_third')?.value;
  if(!f1&&!f2&&!f3)return showAlert('Please select at least 1st place.','error');
  const getNum=id=>{const v=parseFloat((document.getElementById(id)?.value||'').replace('%','').trim());return isNaN(v)?null:v;};
  const existing=getTop3Data();const existingRec=existing[periodKey]||{};
  const registeredUsers=getUsers();
  const getPhoto=(inputId,pos,code)=>document.getElementById(inputId)?._b64||existingRec[pos]?.photo||registeredUsers[code]?.photo||null;
  const todayStr2=new Date().toISOString().slice(0,10);
  const curPeriod=PROD_CUTOFFS.find(p=>todayStr2>=p.opens&&todayStr2<=p.cutoff)||PROD_CUTOFFS.find(p=>p.cutoff>todayStr2);
  const record={
    period:`${MONTHS[parseInt(mo)-1]} ${yr}`,
    periodCutoff:curPeriod?.cutoff||null,
    first:f1?{...getAdv(f1),note:document.getElementById('top3_first_note')?.value.trim()||'',ntu4:getNum('top3_first_ntu4'),ntu15:getNum('top3_first_ntu15'),persistency:getNum('top3_first_pers'),photo:getPhoto('top3_first_photo','first',f1)}:null,
    second:f2?{...getAdv(f2),note:document.getElementById('top3_second_note')?.value.trim()||'',ntu4:getNum('top3_second_ntu4'),ntu15:getNum('top3_second_ntu15'),persistency:getNum('top3_second_pers'),photo:getPhoto('top3_second_photo','second',f2)}:null,
    third:f3?{...getAdv(f3),note:document.getElementById('top3_third_note')?.value.trim()||'',ntu4:getNum('top3_third_ntu4'),ntu15:getNum('top3_third_ntu15'),persistency:getNum('top3_third_pers'),photo:getPhoto('top3_third_photo','third',f3)}:null,
  };
  const data=getTop3Data();data[periodKey]=record;
  saveTop3Data(data);
  if(window.FB_READY)window.FB.saveTop3(periodKey,record).catch(e=>console.error('Top3 Firestore save failed:',e));
  renderTop3();
  const fb=document.getElementById('top3SaveFeedback');if(fb){fb.style.display='block';setTimeout(()=>fb.style.display='none',2500);}
  // Send inbox announcement to all advisors
  if(window.FB_READY&&record.first){
    const msg=`🏆 ${record.period} Top Advisors — 1st: ${record.first.name}${record.second?' · 2nd: '+record.second.name:''}${record.third?' · 3rd: '+record.third.name:''}. Well done to everyone who gave their best this month!`;
    ADVISOR_LIST.forEach(a=>{window.FB.sendInbox({to:a.code,from:'SYSTEM',fromName:'Team Buffalos',title:msg,body:'',type:'notice'}).catch(()=>{});});
  }
}

function populateTop3Selects(){
  const advisors=Object.values(getUsers()).filter(u=>!u.isManager&&!u.isOps);
  const opts='<option value="">—</option>'+[...ADVISOR_LIST,...advisors.filter(u=>!ADVISOR_LIST.find(a=>a.code===u.code))].map(a=>`<option value="${a.code}">${a.name}</option>`).join('');
  ['top3_first','top3_second','top3_third'].forEach(id=>{const el=document.getElementById(id);if(el)el.innerHTML=opts.replace('<option value="">—</option>',`<option value="">${el.options[0]?.text||'—'}</option>`);});
  prefillTop3Form();
}

function prefillTop3Form(){
  const mo=document.getElementById('statsPeriodMonth')?.value||('0'+(new Date().getMonth()+1)).slice(-2);
  const yr=document.getElementById('statsPeriodYear')?.value||new Date().getFullYear();
  const periodKey=`${yr}-${mo}`;
  const data=getTop3Data();
  const rec=data[periodKey];
  const _fill=(pos,selectId,noteId,ntu4Id,ntu15Id,persId,imgId,fileId)=>{
    const r=rec?.[pos];
    const sel=document.getElementById(selectId);
    if(sel)sel.value=r?.code||'';
    const noteEl=document.getElementById(noteId);
    if(noteEl)noteEl.value=r?.note||'';
    const ntu4El=document.getElementById(ntu4Id);
    if(ntu4El)ntu4El.value=r?.ntu4!=null?r.ntu4:'';
    const ntu15El=document.getElementById(ntu15Id);
    if(ntu15El)ntu15El.value=r?.ntu15!=null?r.ntu15:'';
    const persEl=document.getElementById(persId);
    if(persEl)persEl.value=r?.persistency!=null?r.persistency:'';
    if(r?.code)loadTop3ProfilePhoto(selectId,imgId,fileId);
    else{const imgEl=document.getElementById(imgId);if(imgEl)imgEl.innerHTML='📷';}
  };
  _fill('first','top3_first','top3_first_note','top3_first_ntu4','top3_first_ntu15','top3_first_pers','top3_first_img','top3_first_photo');
  _fill('second','top3_second','top3_second_note','top3_second_ntu4','top3_second_ntu15','top3_second_pers','top3_second_img','top3_second_photo');
  _fill('third','top3_third','top3_third_note','top3_third_ntu4','top3_third_ntu15','top3_third_pers','top3_third_img','top3_third_photo');
}

