function renderDailyBrief(){
  const el=document.getElementById('hubDailyBrief');if(!el)return;
  if(!currentUser){el.style.display='none';return;}
  el.style.display='block';
  const today=new Date();
  const d=today.getDate(),m=today.getMonth(),y=today.getFullYear();
  const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const items=[];
  const isOps=currentUser.isManager||currentUser.isOps;

  // Production cut-off countdown (from PROD_CUTOFFS)
  const todayStr=y+'-'+(''+(m+1)).padStart(2,'0')+'-'+(''+d).padStart(2,'0');
  let cutoffEntry=PROD_CUTOFFS.find(p=>p.cutoff>=todayStr);
  if(!cutoffEntry)cutoffEntry=PROD_CUTOFFS[PROD_CUTOFFS.length-1];
  const cutoffParts=cutoffEntry.cutoff.split('-');
  const cutoff=new Date(+cutoffParts[0],+cutoffParts[1]-1,+cutoffParts[2],20,0,0);
  const daysLeft=Math.ceil((cutoff-today)/(86400000));
  items.push({icon:'📋',text:daysLeft<=0?'<b>Production cut-off TODAY at 20:00</b> — all cases must be on Connect Me':daysLeft===1?'<b>Production cut-off TOMORROW at 20:00</b> — final cases must be submitted today':`<b>Production cut-off in ${daysLeft} days</b> — ${cutoff.getDate()} ${MONTHS[cutoff.getMonth()]}`});

  // Collection day
  if(d===19)items.push({icon:'💳',text:'<b>Collection day tomorrow (20th)</b> — remind all debit order clients to ensure funds are available. Check Connect Me.'});
  if(d===20)items.push({icon:'💳',text:'<b>Collection day today</b> — debit orders running. Confirm all orders are active and loaded.'});

  // Today's diary appointments — ops/manager see all, advisors see only their own
  const todayKey=y+'-'+(''+(m+1)).padStart(2,'0')+'-'+(''+d).padStart(2,'0');
  const todayEvs=diaryGetEvents().filter(e=>e.date===todayKey&&(isOps||(e.advisorCode===currentUser.code||e.advisorCode==='ALL')));
  if(todayEvs.length)items.push({icon:'🗓️',text:`<b>${todayEvs.length} appointment${todayEvs.length>1?'s':''} today:</b> `+todayEvs.map(e=>(isOps?`${e.advisorName} — `:'')+`${e.title}${e.startTime?' at '+e.startTime.slice(0,5):''}`).join(', ')});
  else items.push({icon:'🗓️',text:'No appointments logged for today in your diary.'});

  // Day of week motivation
  const dow=today.getDay();
  const dayTips={1:'<b>Monday:</b> Set the week\'s targets with your team first thing.',2:'<b>Tuesday:</b> Mid-week push — check pipeline and follow up on quotes.',3:'<b>Wednesday:</b> Ideal day for school visits and presentations.',4:'<b>Thursday:</b> Review submissions in progress before Friday.',5:'<b>Friday:</b> Confirm all cases are on Connect Me before end of day.',6:'<b>Saturday:</b> Quieter day — great time to plan next week.',0:'<b>Sunday:</b> Rest and prepare — week starts tomorrow.'};
  if(dayTips[dow])items.push({icon:'💡',text:dayTips[dow]});

  el.innerHTML=`<div class="brief-card">
    <div class="brief-title">📋 Daily Brief — ${DAYS[dow]}, ${d} ${MONTHS[m]} ${y}</div>
    ${items.map(i=>`<div class="brief-item"><span class="brief-item-icon">${i.icon}</span><span>${i.text}</span></div>`).join('')}
  </div>`;
}
