function _prodCountdownBg(daysLeft){
  if(daysLeft<=0) return{bg:'linear-gradient(135deg,#7f1d1d,#dc2626)',icon:'🚨'};
  if(daysLeft<=3) return{bg:'linear-gradient(135deg,#991b1b,#dc2626)',icon:'🚨'};
  if(daysLeft<=7) return{bg:'linear-gradient(135deg,#9a3412,#c2410c)',icon:'⚠️'};
  if(daysLeft<=14)return{bg:'linear-gradient(135deg,#78350f,#b45309)',icon:'⏳'};
  return               {bg:'linear-gradient(135deg,#14532d,#15803d)',icon:'📋'};
}
function renderProdCountdownStandalone(){
  const el=document.getElementById('prodCountdownStandalone');
  if(!el)return;
  const now=new Date();
  const todayStr=now.toISOString().slice(0,10);
  if(typeof PROD_CUTOFFS==='undefined'){el.style.display='none';return;}
  const cur=PROD_CUTOFFS.find(p=>todayStr<=p.cutoff);
  if(!cur){el.style.display='none';return;}
  const cutoffDate=new Date(cur.cutoff+'T20:00:00');
  const diff=cutoffDate-now;
  if(diff<=0){el.style.display='none';return;}
  const days=Math.floor(diff/86400000);
  const hrs=Math.floor((diff%86400000)/3600000);
  const mins=Math.floor((diff%3600000)/60000);
  const isToday=cutoffDate.toDateString()===now.toDateString();
  const {bg,icon}=_prodCountdownBg(isToday?0:days+(hrs>0?1:0));
  const timeLabel=isToday?`${icon} Closes TODAY at 20:00`:`${cur.cutoff} at 20:00`;
  const daysLabel=diff>86400000?`${days}d ${hrs}h ${mins}m remaining`:`${hrs}h ${mins}m remaining`;
  el.style.display='block';
  el.innerHTML=`<div style="background:${bg};border-radius:16px;padding:14px 18px;box-shadow:0 4px 20px rgba(0,0,0,0.25);transition:background .6s;">
    <div style="font-size:10px;font-weight:700;color:rgba(255,255,255,0.6);text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;text-align:center;">${icon} Production Cut-off — ${timeLabel}</div>
    <div style="display:flex;gap:8px;justify-content:center;margin-bottom:8px;">
      ${days>0?`<div style="text-align:center;background:rgba(255,255,255,0.18);border-radius:10px;padding:8px 16px;min-width:56px;"><div style="font-size:28px;font-weight:700;color:#fff;line-height:1;">${days}</div><div style="font-size:9px;color:rgba(255,255,255,0.6);margin-top:2px;letter-spacing:.5px;">DAYS</div></div>`:''}
      <div style="text-align:center;background:rgba(255,255,255,0.18);border-radius:10px;padding:8px 16px;min-width:56px;"><div style="font-size:28px;font-weight:700;color:#fff;line-height:1;">${hrs}</div><div style="font-size:9px;color:rgba(255,255,255,0.6);margin-top:2px;letter-spacing:.5px;">HRS</div></div>
      <div style="text-align:center;background:rgba(255,255,255,0.18);border-radius:10px;padding:8px 16px;min-width:56px;"><div style="font-size:28px;font-weight:700;color:#fff;line-height:1;">${mins}</div><div style="font-size:9px;color:rgba(255,255,255,0.6);margin-top:2px;letter-spacing:.5px;">MIN</div></div>
    </div>
    <div style="font-size:11px;color:rgba(255,255,255,0.65);text-align:center;">All cases must be on Connect Me · ${daysLabel}</div>
  </div>`;
  clearTimeout(window._prodTimer);
  window._prodTimer=setTimeout(renderProdCountdownStandalone,60000);
}

// ── REMINDERS: PRODUCTION COUNTDOWN + QLINK RUNS + PAYMENT DATES ──
const PAY_DATES=[15,20,25,26,29,30];

function getNextPayDate(){
  const now=new Date();const d=now.getDate();const m=now.getMonth();const y=now.getFullYear();
  for(let i=0;i<PAY_DATES.length;i++){
    let pd=new Date(y,m,PAY_DATES[i],7,0,0);
    if(pd.getDay()===0)pd=new Date(y,m,PAY_DATES[i]-2,7,0,0);
    if(pd>now)return{date:pd,day:PAY_DATES[i]};
    if(pd.toDateString()===now.toDateString())return{date:pd,day:PAY_DATES[i],isToday:true};
  }
  let pd=new Date(y,m+1,PAY_DATES[0],7,0,0);
  if(pd.getDay()===0)pd=new Date(y,m+1,PAY_DATES[0]-2,7,0,0);
  return{date:pd,day:PAY_DATES[0]};
}

function fmtCountdown(diff){
  const days=Math.floor(diff/86400000);
  const hrs=Math.floor((diff%86400000)/3600000);
  const mins=Math.floor((diff%3600000)/60000);
  const blocks=[];
  if(days>0)blocks.push({v:days,l:'D'});
  blocks.push({v:hrs,l:'H'},{v:mins,l:'M'});
  return blocks.map(b=>`<div style="text-align:center;background:rgba(255,255,255,0.12);border-radius:8px;padding:4px 10px;min-width:36px;">
    <div style="font-size:18px;font-weight:700;color:#fff;line-height:1;">${b.v}</div>
    <div style="font-size:9px;color:rgba(255,255,255,0.5);margin-top:1px;">${b.l}</div>
  </div>`).join('');
}

function renderHubPaymentReminder(){
  const el=document.getElementById('hubPaymentReminder');
  if(!el)return;
  const now=new Date();
  const next=getNextPayDate();
  const diff=next.date-now;
  const daysLeft=Math.floor(diff/86400000);
  if(!next.isToday&&daysLeft>3){el.innerHTML='';checkRemindersVisible();return;}
  const isToday=next.isToday||daysLeft===0;
  const soon=daysLeft<=2&&!isToday;
  const bg=isToday?'#fef2f2':soon?'#fef3c7':'#f0f9ff';
  const border=isToday?'#dc2626':soon?'#d97706':'#0891b2';
  const titleColor=isToday?'#dc2626':soon?'#92400e':'#075985';
  const subColor=isToday?'#991b1b':soon?'#b45309':'#0369a1';
  const title=isToday
    ?`💳 Collection day — ${next.day}th`
    :`💳 Collection in ${daysLeft} day${daysLeft!==1?'s':''} — ${next.day}th`;
  const sub='Client debit orders run on this date — ensure all debit orders are active and loaded.';
  el.innerHTML=`<div style="background:${bg};border-radius:10px;padding:10px 12px;display:flex;align-items:flex-start;gap:10px;border-left:3px solid ${border};">
    <div>
      <div style="font-size:12px;font-weight:700;color:${titleColor};">${title}</div>
      <div style="font-size:10px;color:${subColor};margin-top:2px;">${sub}</div>
    </div>
  </div>`;
  checkRemindersVisible();
}

function checkRemindersVisible(){
  const section=document.getElementById('hubRemindersSection');
  if(!section)return;
  const countdown=document.getElementById('hubCountdownSection');
  const payment=document.getElementById('hubPaymentReminder');
  const hasContent=(countdown&&countdown.innerHTML.trim())||(payment&&payment.innerHTML.trim());
  section.style.display=hasContent?'block':'none';
}

function renderHubCountdown(){
  const el=document.getElementById('hubCountdownSection');
  if(!el)return;
  const now=new Date();
  const todayStr=now.toISOString().slice(0,10);
  const html=[];

  // ── Next Qlink runs ──
  if(typeof QLINK_DATES!=='undefined'){
    const allRuns=[];
    Object.entries(QLINK_DATES).forEach(([month,runs])=>{
      runs.forEach(r=>{if(r.d>=todayStr)allRuns.push({date:r.d,month});});
    });
    allRuns.sort((a,b)=>a.date.localeCompare(b.date));
    if(allRuns.length){
      const next=allRuns[0];
      const fd=new Date(next.date+'T13:00:00');
      const diff=fd-now;
      const isToday=next.date===todayStr;
      const urgent=diff<86400000;
      const colour=urgent?'#fca5a5':'rgba(255,255,255,0.85)';
      const next3=allRuns.slice(0,3).map((r,i)=>`<div style="display:flex;justify-content:space-between;font-size:11px;color:${i===0?'#0d1f3c':'#9ca3af'};padding:2px 0;${i===0?'font-weight:700;':''}">
        <span>${r.date} <span style="font-size:10px;color:#9ca3af;">${r.month}</span></span>
        <span>${r.date===todayStr?'<span style="color:#dc2626;font-weight:700;">TODAY — before 13:00</span>':i===0?'<span style="color:#c9922a;">Next run</span>':''}</span>
      </div>`).join('');
      html.push(`<div style="background:#f8f7f4;border-radius:10px;padding:8px 12px;border-left:3px solid #c9922a;">
        <div style="font-size:10px;font-weight:700;color:#c9922a;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">⚡ Qlink runs — submit before 13:00</div>
        ${next3}
      </div>`);
    }
  }

  el.innerHTML=html.join('');
  el.style.display=html.length?'flex':'none';
  el.style.flexDirection='column';
  el.style.gap='6px';
  checkRemindersVisible();
  clearTimeout(window._countdownTimer);
  window._countdownTimer=setTimeout(()=>{renderHubCountdown();renderHubPaymentReminder();},60000);
}


// ── OPS LANDING ──
function renderOpsLand(){
  renderHubCountdown();
  const isOps=currentUser&&(currentUser.isOps||currentUser.isManager);
  // Show/hide manager tiles
  ['oltDailyOps','oltTeam','oltRecruit','oltPrecan','opsTodaySnapshot'].forEach(id=>{
    const el=document.getElementById(id);if(el)el.style.display=isOps?'block':'none';
  });
  if(!isOps)return;

  // Build urgency from ops data
  const now=new Date();
  const mins=now.getHours()*60+now.getMinutes();
  const alerts=[];

  // Pre-cancellation deadline
  const precanLeft=12*60-mins;
  if(precanLeft>0&&precanLeft<=240)alerts.push('🚨 Pre-can deadline in '+Math.floor(precanLeft/60)+'h '+( precanLeft%60)+'m');
  else if(precanLeft<=0&&precanLeft>-60)alerts.push('⏰ Pre-cancellation deadline passed today');

  // Payment date check
  const d=now.getDate();
  if(d===15)alerts.push('💳 15th pay clients — confirm deductions today');
  if(d===19)alerts.push('💳 General pay date tomorrow — remind clients with debit orders to ensure funds are available. Check Connect Me for your affected clients.');
  if(d===12)alerts.push('📋 Submit 15th-pay cases by today (cut-off)');

  // Badge
  const badge=document.getElementById('opsTileBadge');
  const navBadge=document.getElementById('opsNavBadge');
  const urgBanner=document.getElementById('opsUrgentBanner');
  const urgText=document.getElementById('opsUrgentText');
  const alertStrip=document.getElementById('opsAlertStrip');
  const tile=document.getElementById('opsTile');
  const dailyBadge=document.getElementById('oltDailyOpsBadge');

  if(alerts.length>0){
    if(badge)badge.style.display='inline-block';
    if(navBadge)navBadge.style.display='inline-block';
    if(urgBanner)urgBanner.style.display='block';
    if(urgText)urgText.textContent=alerts[0];
    if(alertStrip)alertStrip.style.display='none';
    if(tile)tile.classList.add('ops-urgent-glow');
    if(dailyBadge)dailyBadge.style.display='inline-block';
  } else {
    if(badge)badge.style.display='none';
    if(navBadge)navBadge.style.display='none';
    if(urgBanner)urgBanner.style.display='none';
    if(alertStrip)alertStrip.style.display='none';
    if(tile)tile.classList.remove('ops-urgent-glow');
    if(dailyBadge)dailyBadge.style.display='none';
  }

  // Today snapshot
  const snap=document.getElementById('opsTodayContent');
  if(snap){
    const dayNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    const lines=[
      '<b>'+dayNames[now.getDay()]+', '+now.toLocaleDateString('en-ZA',{day:'numeric',month:'long',year:'numeric'})+'</b>',
      d===12?'📋 <b>Cut-off:</b> Submit 15th-pay cases today':'',
      d===15?'💳 <b>Pay day:</b> 15th pay clients — confirm deductions':'',
      d===19?'💳 <b>General pay date tomorrow:</b> Remind debit order clients to have funds available — check Connect Me for affected clients':'',
      precanLeft>0&&precanLeft<=480?'🚨 <b>Pre-can deadline:</b> '+Math.floor(precanLeft/60)+'h '+(precanLeft%60)+'m remaining':'',
      precanLeft<=0&&precanLeft>-120?'⏰ Pre-cancellation window closed for today':'',
    ].filter(Boolean);
    snap.innerHTML=lines.join('<br>')||'<span style="color:#9ca3af;">No urgent items today.</span>';
  }

  // Update ops tile desc
  const desc=document.getElementById('opsTileDesc');
  if(desc)desc.textContent=alerts.length?alerts.length+' alert'+(alerts.length>1?'s':'')+' — tap to manage':'Manage your team & tasks';
  renderYTDTop3();
}

// ── RECRUITMENT PIPELINE ──
const REC_STATUS_LABELS={
  contact:'🔵 Initial contact needed',
  training:'📚 Training',
  interview:'🟡 Interview pending',
  onboarding:'🟠 Onboarding',
  onboarded:'✅ Onboarded',
  declined:'❌ Declined',
  left:'🚪 Left / Resigned',
  left:'🚪 Left / Resigned'
};

function getRecruits(){try{return JSON.parse(localStorage.getItem('tl_recruits')||'[]');}catch(e){return[];}}
function saveRecruits(d){
  try{localStorage.setItem('tl_recruits',JSON.stringify(d));}catch(e){}
}

function addRecruit(){
  // ensure date defaults to today if not set

  const fname=document.getElementById('rec-fname').value.trim();
  const lname=document.getElementById('rec-lname').value.trim();
  const cell=document.getElementById('rec-cell').value.trim();
  const idno=document.getElementById('rec-id').value.trim();
  const area=document.getElementById('rec-area').value.trim();
  const ref=document.getElementById('rec-ref').value.trim();
  const status=document.getElementById('rec-status').value;
  const date=document.getElementById('rec-date').value;
  const notes=document.getElementById('rec-notes').value.trim();
  if(!fname||!lname)return alert('Please enter at least a first name and surname.');
  const recruits=getRecruits();
  recruits.unshift({
    id:Date.now()+'_'+Math.random().toString(36).slice(2),
    fname,lname,cell,idno,area,ref,status,date,notes,
    addedBy:currentUser.name,
    addedAt:new Date().toISOString()
  });
  saveRecruits(recruits);
  ['rec-fname','rec-lname','rec-cell','rec-id','rec-area','rec-ref','rec-notes'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('rec-status').value='contact';
  document.getElementById('rec-date').value='';
  renderRecruits();
}


function recEdit(id){
  const r=getRecruits().find(x=>x.id===id);
  if(!r)return;
  // Populate form with existing data
  document.getElementById('rec-fname').value=r.fname||'';
  document.getElementById('rec-lname').value=r.lname||'';
  document.getElementById('rec-cell').value=r.cell||'';
  document.getElementById('rec-id').value=r.idno||'';
  document.getElementById('rec-area').value=r.area||'';
  document.getElementById('rec-ref').value=r.ref||'';
  document.getElementById('rec-status').value=r.status||'contact';
  document.getElementById('rec-date').value=r.date||'';
  document.getElementById('rec-notes').value=r.notes||'';
  // Change button to update mode
  const btn=document.querySelector('#page-recruit .add-btn');
  if(btn){btn.textContent='Update candidate';btn.onclick=function(){recUpdate(id);};}
  // Scroll to form
  document.getElementById('rec-fname').scrollIntoView({behavior:'smooth',block:'center'});
}
function recUpdate(id){
  const recruits=getRecruits();
  const c=recruits.find(x=>x.id===id);
  if(!c)return;
  c.fname=document.getElementById('rec-fname').value.trim();
  c.lname=document.getElementById('rec-lname').value.trim();
  c.cell=document.getElementById('rec-cell').value.trim();
  c.idno=document.getElementById('rec-id').value.trim();
  c.area=document.getElementById('rec-area').value.trim();
  c.ref=document.getElementById('rec-ref').value.trim();
  c.status=document.getElementById('rec-status').value;
  c.date=document.getElementById('rec-date').value;
  c.notes=document.getElementById('rec-notes').value.trim();
  saveRecruits(recruits);
  // Reset form
  ['rec-fname','rec-lname','rec-cell','rec-id','rec-area','rec-ref','rec-notes'].forEach(fid=>{const el=document.getElementById(fid);if(el)el.value='';});
  document.getElementById('rec-status').value='contact';
  document.getElementById('rec-date').value='';
  const btn=document.querySelector('#page-recruit .add-btn');
  if(btn){btn.textContent='Add to pipeline';btn.onclick=addRecruit;}
  renderRecruits();
}

function recUpdateStatus(id,val){
  const r=getRecruits();const c=r.find(x=>x.id===id);if(c){c.status=val;saveRecruits(r);renderRecruits();}
}

function recUpdateNotes(id,val){
  const r=getRecruits();const c=r.find(x=>x.id===id);if(c){c.notes=val;saveRecruits(r);}
}

function recDelete(id){
  if(!confirm('Remove this candidate from the pipeline?'))return;
  saveRecruits(getRecruits().filter(x=>x.id!==id));renderRecruits();
}


function renderDirectory(){
  const grid=document.getElementById('internalDirGrid');
  if(!grid)return;
  const loadAndRender=()=>{
    const users=getUsers();
    const advisors=Object.values(users).sort((a,b)=>a.name.localeCompare(b.name));
    if(!advisors.length){grid.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:1rem;grid-column:1/-1;">No team members registered yet.</div>';return;}
    const colors=['#0d1f3c','#1b4f8a','#c9922a','#059669','#7c3aed','#be185d','#0891b2','#dc2626','#92400e','#065f46'];
    grid.innerHTML=advisors.map((u,i)=>`
      <div class="dir-card">
        <div class="dir-av" style="background:${colors[i%colors.length]};">${u.name.charAt(0)}</div>
        <div class="dir-info">
          <div class="dir-name">${u.name}</div>
          <div class="dir-role">${u.isManager?'Sales Manager':u.isOps?'Operations':'Advisor'} · <span style="font-family:monospace;">${u.code}</span></div>
          ${u.email?`<a class="dir-wa" href="mailto:${u.email}" style="background:#f0f9ff;border-color:#bae6fd;">✉️ Email</a>`:''}
        </div>
      </div>`).join('');
  };
  if(window.FB_READY&&window.FB.getAllUsers){
    window.FB.getAllUsers().then(fbUsers=>{
      if(fbUsers&&Object.keys(fbUsers).length>0){
        const local=getUsers();Object.assign(local,fbUsers);saveUsers(local);
      }
      loadAndRender();
    }).catch(loadAndRender);
  } else {
    loadAndRender();
  }
}

function renderRecruits(){
  let r=getRecruits();
  const sf=(document.getElementById('recStatusFilter')||{}).value||'';
  if(sf)r=r.filter(x=>x.status===sf);

  // Stats (always from full list)
  const all=getRecruits();
  const el=id=>document.getElementById(id);
  const onboardedCount=all.filter(x=>x.status==='onboarded').length;
  const leftCount=all.filter(x=>x.status==='left').length;
  const manpower=11+onboardedCount-leftCount;
  if(el('recManpower'))el('recManpower').textContent=manpower;
  if(el('recStatTotal'))el('recStatTotal').textContent=all.length;
  if(el('recStatContact'))el('recStatContact').textContent=all.filter(x=>x.status==='contact').length;
  if(el('recStatInterview'))el('recStatInterview').textContent=all.filter(x=>x.status==='interview').length;
  if(el('recStatOnboarded'))el('recStatOnboarded').textContent=onboardedCount;

  const tbody=document.getElementById('recBody');
  const empty=document.getElementById('recEmpty');
  const table=document.getElementById('recTable');
  if(!r.length){if(tbody)tbody.innerHTML='';if(empty)empty.style.display='block';if(table)table.style.display='none';return;}
  if(empty)empty.style.display='none';
  if(table)table.style.display='table';

  const statusColors={contact:'#dbeafe',training:'#f0e6ff',interview:'#fef3c7',onboarding:'#ffedd5',onboarded:'#dcfce7',declined:'#fee2e2',left:'#f3f4f6'};
  tbody.innerHTML=r.map(c=>`
    <tr style="background:${statusColors[c.status]||'#fff'}20;">
      <td><div style="font-weight:700;font-size:12px;color:#0d1f3c;">${c.fname} ${c.lname}</div><div style="font-size:10px;color:#9ca3af;">${c.idno||''}</div></td>
      <td style="font-size:12px;">${c.cell||'—'}</td>
      <td style="font-size:12px;color:#6b7280;">${c.area||'—'}</td>
      <td style="font-size:11px;color:#6b7280;">${c.ref||'—'}</td>
      <td>
        <select onchange="recUpdateStatus('${c.id}',this.value)" style="font-size:11px;border:1px solid #e5e7eb;border-radius:6px;padding:2px 6px;background:#fff;">
          ${Object.entries(REC_STATUS_LABELS).map(([k,v])=>`<option value="${k}"${c.status===k?' selected':''}>${v}</option>`).join('')}
        </select>
      </td>
      <td style="font-size:11px;color:#6b7280;white-space:nowrap;">${c.date||'—'}</td>
      <td><textarea onblur="recUpdateNotes('${c.id}',this.value)" style="font-size:11px;border:1px solid #e5e7eb;border-radius:6px;padding:4px;width:140px;min-height:40px;resize:vertical;">${c.notes||''}</textarea></td>
      <td style="white-space:nowrap;">
        <button onclick="recEdit('${c.id}')" style="font-size:11px;background:#0d1f3c;color:#fff;border:none;border-radius:6px;padding:3px 8px;cursor:pointer;margin-bottom:3px;">✏️ Edit</button>
        <button class="del-btn" onclick="recDelete('${c.id}')">✕</button>
      </td>
    </tr>`).join('');
}






// ── IMP SCREENSHOT READER ──
async function handleIMPUpload(input, mode){
  const file = input.files[0];
  if(!file)return;
  const labelEl = document.getElementById(mode==='new'?'impNewLabel':'impRepLabel');
  const statusEl = document.getElementById(mode==='new'?'impNewStatus':'impRepStatus');
  if(labelEl) labelEl.textContent = '⏳ Analysing IMP screenshot...';
  if(statusEl){statusEl.style.display='block';statusEl.textContent='Reading lives and cover amounts...';}

  try {
    const b64 = await new Promise((res,rej)=>{
      const r=new FileReader();
      r.onload=()=>res(r.result.split(',')[1]);
      r.onerror=rej;
      r.readAsDataURL(file);
    });
    const mediaType = file.type || 'image/jpeg';

    const roaPrompt = 'This is an IMP Final Recommendation screen from Sanlam Sky. Is it REPLACEMENT (has Kept Cover + New Cover sections) or NEW BUSINESS (only new policies)? Return ONLY this JSON (no markdown): {"type":"new","new_plan":"All-in-One Plan","new_lives":[{"role":"Main member","name":"John Smith","cover":"R50 000"},{"role":"Spouse","name":"Mary Smith","cover":"R30 000"}],"new_premium":"R450","kept_cover_lives":[{"role":"Main member","name":"John Smith","cover":"R40 000"}],"total_cover":"R50 000","kept_premium":"R350"}';
    const clean = (await callClaudeVision(b64, mediaType, roaPrompt)).replace(/```json|```/g,'').trim();
    const parsed = JSON.parse(clean||'{}');

    // Auto-switch form type based on detected type
    const detectedType = parsed.type || mode === 'rep' ? 'replacement' : 'new';
    if(detectedType === 'replacement' && _roaType !== 'replacement'){
      setROAType('replacement');
    } else if(detectedType === 'new' && _roaType !== 'new'){
      setROAType('new');
    }

    const _normLives = (raw)=>{
      if(Array.isArray(raw) && raw.length) return raw.map(l=>({role:l.role||'Main member',name:l.name||'',cover:l.cover||''}));
      if(typeof raw === 'string' && raw) return [{role:'Main member',name:raw,cover:''}];
      return [{role:'Main member',name:'',cover:''}];
    };

    if(detectedType === 'new' || _roaType === 'new'){
      // New business — fill plans
      if(!_roaPlans.length) _roaPlans = [{plan:'Value Funeral Plan',premium:'',lives:[{role:'Main member',name:'',cover:''}]}];
      const planIdx = _roaPlans.length - 1;
      if(parsed.new_plan) _roaPlans[planIdx].plan = parsed.new_plan;
      if(parsed.new_premium) _roaPlans[planIdx].premium = parsed.new_premium;
      if(parsed.new_lives) _roaPlans[planIdx].lives = _normLives(parsed.new_lives);
      roaRenderPlans();
    } else {
      // Replacement — fill new policies + kept cover notes
      if(!_roaNewPolicies.length) _roaNewPolicies = [{plan:'All-in-One Plan (standalone)',premium:'',lives:[{role:'Main member',name:'',cover:''}]}];
      const idx = _roaNewPolicies.length - 1;
      if(parsed.new_plan) _roaNewPolicies[idx].plan = parsed.new_plan;
      if(parsed.new_premium) _roaNewPolicies[idx].premium = parsed.new_premium;
      if(parsed.new_lives) _roaNewPolicies[idx].lives = _normLives(parsed.new_lives);
      roaRenderNewPolicies();

      // Add kept cover as cancelled policy note if present
      if(parsed.kept_cover && !_roaRepPolicies.some(p=>p.lives===parsed.kept_cover)){
        _roaRepPolicies.push({company:'Previous FSP (Kept Cover)',premium:parsed.kept_premium||'',lives:parsed.kept_cover});
        roaRenderRepPolicies();
      }

      // Store total cover for ROA note
      window._roaTotalCover = parsed.total_cover || '';
    }

    if(labelEl) labelEl.textContent = '✓ Screenshot read — fields updated below';
    const _liveSummary = Array.isArray(parsed.new_lives) ? parsed.new_lives.map(l=>l.name||l.role).join(', ') : (parsed.new_lives||'');
    const summary = detectedType==='replacement'
      ? `✓ Replacement detected — New: ${parsed.new_plan||''} ${parsed.new_premium||''} · Kept cover detected`
      : `✓ New business detected — ${parsed.new_plan||''} · Lives: ${_liveSummary||'see below'}`;
    if(statusEl) statusEl.textContent = summary + '. Review and edit below if needed.';
    roaGenerate();

  } catch(e){
    const isQuota=e.message&&(e.message.includes('quota')||e.message.includes('429'));
    if(labelEl) labelEl.textContent = '⚠️ Fill in manually';
    if(statusEl){statusEl.style.color='#dc2626';statusEl.textContent=isQuota?'AI analysis is temporarily unavailable — please fill in the fields manually.':'Could not read the screenshot. Please fill in the fields manually.';}
  }
  // Clear input so same file can be re-uploaded
  input.value = '';
}

// ── ROA GENERATOR ──
let _roaType = 'new';
let _repReasonType = 'affordability';
let _roaPlans = [];
let _roaRepPolicies = [];
let _roaNewPolicies = [];

function setRepReason(type){
  _repReasonType=type;
  [['Afford','affordability'],['Benefits','benefits'],['Mix','mix']].forEach(([id,val])=>{
    const btn=document.getElementById(`roaRepBtn${id}`);
    if(!btn)return;
    const active=val===type;
    btn.style.background=active?'#0d1f3c':'#fff';
    btn.style.color=active?'#fff':'#0d1f3c';
    btn.style.borderColor=active?'#0d1f3c':'#e5e7eb';
  });
  const bc=document.getElementById('roaBenefitChecks');
  const ad=document.getElementById('roaAffordDetail');
  if(bc)bc.style.display=(type==='benefits'||type==='mix')?'block':'none';
  if(ad)ad.style.display=(type==='affordability'||type==='mix')?'block':'none';
  roaGenerate();
}

const ROA_PLANS = ['Value Funeral Plan','Enhanced Priority Funeral Plan','All-in-One Plan (standalone)','Immediate Life Cover (ILC)','Essential Med'];
const ROA_LIFE_ROLES = ['Main member','Spouse','Child 1','Child 2','Child 3','Child 4','Extended family member'];
const ROA_REASONS = {
  align:'The client chose to align their existing cover amount with the new policy.',
  better:'The client selected the new policy based on its superior product benefits and overall value for money.',
  nopaidup:'The existing policy does not include a paid-up benefit. The new policy provides this benefit, which was an important consideration for the client.',
  nocashback:'The existing policy does not include a cashback benefit. The new policy includes a cashback option, which was a key factor in the client\'s decision.',
  norepatriation:'The existing policy does not include a repatriation benefit. The new policy provides full repatriation cover.',
  claim_rejected:'The client\'s claim was previously rejected by the existing insurer, resulting in the decision to replace the policy with a more suitable product.',
  consolidate_cover:'The client chose to consolidate multiple existing policies into a single comprehensive policy to simplify their cover.'
};

function setROAType(type){
  _roaType = type;
  const btnNew = document.getElementById('roaBtnNew');
  const btnRep = document.getElementById('roaBtnRep');
  const newForm = document.getElementById('roaNewForm');
  const repForm = document.getElementById('roaRepForm');
  if(type==='new'){
    btnNew.style.background='#0d1f3c';btnNew.style.color='#fff';btnNew.style.borderColor='#0d1f3c';
    btnRep.style.background='#fff';btnRep.style.color='#0d1f3c';btnRep.style.borderColor='#e5e7eb';
    if(newForm)newForm.style.display='block';
    if(repForm)repForm.style.display='none';
    if(!_roaPlans.length)roaAddPlan();
  } else {
    btnRep.style.background='#0d1f3c';btnRep.style.color='#fff';btnRep.style.borderColor='#0d1f3c';
    btnNew.style.background='#fff';btnNew.style.color='#0d1f3c';btnNew.style.borderColor='#e5e7eb';
    if(newForm)newForm.style.display='none';
    if(repForm)repForm.style.display='block';
    if(!_roaRepPolicies.length)roaAddRepPolicy();
    if(!_roaNewPolicies.length)roaAddNewPolicy();
    setRepReason(_repReasonType||'affordability');
    return; // setRepReason calls roaGenerate
  }
  roaGenerate();
}

function roaAddPlan(){
  _roaPlans.push({plan:'Value Funeral Plan',premium:'',lives:[{role:'Main member',name:'',cover:''}]});
  roaRenderPlans();
}

function roaAddLife(planIdx,listType){
  const usedRoles = listType==='plan' ? _roaPlans[planIdx].lives.map(l=>l.role) : _roaNewPolicies[planIdx].lives.map(l=>l.role);
  const nextRole = ROA_LIFE_ROLES.find(r=>!usedRoles.includes(r))||'Extended family member';
  if(listType==='plan'){
    _roaPlans[planIdx].lives.push({role:nextRole,name:'',cover:''});
    roaRenderPlans();
  } else {
    _roaNewPolicies[planIdx].lives.push({role:nextRole,name:'',cover:''});
    roaRenderNewPolicies();
  }
  roaGenerate();
}

