// ── DIARY / PLANNER ──────────────────────────────────────────────────────────
const TC_TERMS_2026=[
  {start:new Date(2026,0,14),end:new Date(2026,2,27),label:'Term 1'},
  {start:new Date(2026,3,14),end:new Date(2026,5,26),label:'Term 2'},
  {start:new Date(2026,6,14),end:new Date(2026,8,25),label:'Term 3'},
  {start:new Date(2026,9,7),end:new Date(2026,11,4),label:'Term 4'},
];
const TC_PUBHOLS_2026={
  '2026-01-01':'New Year\'s Day','2026-03-21':'Human Rights Day',
  '2026-04-03':'Good Friday','2026-04-06':'Family Day',
  '2026-04-27':'Freedom Day','2026-05-01':'Workers\' Day',
  '2026-06-16':'Youth Day','2026-08-10':'National Women\'s Day (observed)',
  '2026-09-24':'Heritage Day','2026-12-16':'Day of Reconciliation',
  '2026-12-25':'Christmas Day','2026-12-26':'Day of Goodwill',
};
const TC_EXAMS_2026=[
  {start:new Date(2026,2,9), end:new Date(2026,2,27),label:'Term 1 tests'},
  {start:new Date(2026,5,1), end:new Date(2026,5,26),label:'Mid-year exams'},
  {start:new Date(2026,7,24),end:new Date(2026,8,18),label:'Matric prelims'},
  {start:new Date(2026,8,7), end:new Date(2026,8,25),label:'Term 3 tests'},
  {start:new Date(2026,9,26),end:new Date(2026,10,27),label:'Matric finals'},
  {start:new Date(2026,10,2),end:new Date(2026,10,20),label:'Gr 10/11 exams'},
];
function tcIsTerm(d){return TC_TERMS_2026.some(t=>d>=t.start&&d<=t.end);}
function tcPubHol(d){const k=d.getFullYear()+'-'+(''+(d.getMonth()+1)).padStart(2,'0')+'-'+(''+d.getDate()).padStart(2,'0');return TC_PUBHOLS_2026[k]||null;}
function tcIsExam(d){return TC_EXAMS_2026.some(e=>d>=e.start&&d<=e.end);}
function tcExamLabel(d){return TC_EXAMS_2026.find(e=>d>=e.start&&d<=e.end)?.label||null;}

// State
let _diaryView='month',_diaryDate=new Date(),_diaryEditId=null;

function diaryGetEvents(){try{return JSON.parse(localStorage.getItem('tl_diary')||'[]');}catch(e){return[];}}
function diarySaveEvents(arr){localStorage.setItem('tl_diary',JSON.stringify(arr));}
function diaryDateKey(d){return d.getFullYear()+'-'+(''+(d.getMonth()+1)).padStart(2,'0')+'-'+(''+d.getDate()).padStart(2,'0');}
function diaryParseKey(s){const[y,m,d]=s.split('-').map(Number);const dt=new Date(y,m-1,d);dt.setHours(0,0,0,0);return dt;}

function diaryDayClass(date){
  const phol=tcPubHol(date);if(phol)return 'pubhol';
  if(tcIsExam(date))return 'exam';
  if(tcIsTerm(date))return 'term';
  return 'holiday';
}
function diaryIsCutoff(date){const dk=diaryDateKey(date);return PROD_CUTOFFS.some(p=>p.cutoff===dk);}
function diaryIsMiniCutoff(date){
  if(date.getDay()!==5)return false;
  const nextFri=new Date(date);nextFri.setDate(date.getDate()+7);
  const isLastFriday=nextFri.getMonth()!==date.getMonth();
  return !isLastFriday; // every Friday EXCEPT the last one = mini cut-off
}
function diaryIsWorkingDay(date){
  const dow=date.getDay();
  return dow>0&&dow<6&&!tcPubHol(date);
}
function diaryIsQlinkDay(date){
  const dk=diaryDateKey(date);
  return typeof QLINK_DATES!=='undefined'&&Object.values(QLINK_DATES).some(runs=>runs.some(r=>r.d===dk));
}
function diaryGetSystemChips(date,isCutoff){
  const chips=[];
  if(!isCutoff&&diaryIsQlinkDay(date))chips.push({cls:'qlink-lbl',label:'⚡ Qlink 13:00',title:'Qlink run — submit before 13:00'});
  if(diaryIsWorkingDay(date))chips.push({cls:'precan-lbl',label:'⚠️ Precan 08:00',title:'Pre-cancellation list at 08:00'});
  return chips;
}


function diaryVisibleEvents(){
  const events=diaryGetEvents();
  const isMgr=currentUser?.isManager||currentUser?.isOps;
  if(isMgr){
    const f=document.getElementById('diaryAdvisorFilter')?.value||'';
    return f?events.filter(e=>e.advisorCode===f||e.advisorCode==='ALL'):events;
  }
  return events.filter(e=>e.advisorCode===currentUser?.code||e.advisorCode==='ALL');
}
function diaryEventsForKey(k){return diaryVisibleEvents().filter(e=>e.date===k).sort((a,b)=>(a.startTime||'').localeCompare(b.startTime||''));}

function renderDiary(){
  const el=document.getElementById('diaryContent');if(!el||!currentUser)return;
  const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  const DAYS3=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const DAYS1=['S','M','T','W','T','F','S'];

  // Manager filter
  const isMgr=currentUser.isManager||currentUser.isOps;
  const mgrEl=document.getElementById('diaryMgrFilter');
  if(mgrEl){
    mgrEl.style.display=isMgr?'block':'none';
    if(isMgr){
      const sel=document.getElementById('diaryAdvisorFilter');
      if(sel&&sel.options.length<=1){
        ADVISOR_LIST.forEach(a=>{const o=document.createElement('option');o.value=a.code;o.textContent=a.name;sel.appendChild(o);});
      }
    }
  }

  // Period label + render
  if(_diaryView==='month'){
    document.getElementById('diaryPeriodLbl').textContent=MONTHS[_diaryDate.getMonth()]+' '+_diaryDate.getFullYear();
    _renderDiaryMonth(el,MONTHS,DAYS3);
  } else if(_diaryView==='week'){
    const ws=new Date(_diaryDate);ws.setDate(_diaryDate.getDate()-_diaryDate.getDay());
    const we=new Date(ws);we.setDate(ws.getDate()+6);
    document.getElementById('diaryPeriodLbl').textContent=MONTHS[ws.getMonth()].slice(0,3)+' '+ws.getDate()+' – '+MONTHS[we.getMonth()].slice(0,3)+' '+we.getDate()+' '+we.getFullYear();
    _renderDiaryWeek(el,ws,DAYS3,DAYS1,MONTHS);
  } else {
    document.getElementById('diaryPeriodLbl').textContent=DAYS3[_diaryDate.getDay()]+', '+_diaryDate.getDate()+' '+MONTHS[_diaryDate.getMonth()]+' '+_diaryDate.getFullYear();
    _renderDiaryDay(el,MONTHS);
  }
  document.querySelectorAll('.diary-view-tab').forEach(t=>t.classList.toggle('active',t.dataset.view===_diaryView));
}

function _renderDiaryMonth(el,MONTHS,DAYS){
  const today=new Date();today.setHours(0,0,0,0);
  const y=_diaryDate.getFullYear(),m=_diaryDate.getMonth();
  const first=new Date(y,m,1),last=new Date(y,m+1,0);
  let h='<div class="diary-cal-hdr">'+DAYS.map(d=>`<div class="diary-cal-dow">${d.slice(0,2)}</div>`).join('')+'</div>';
  h+='<div class="diary-cal-grid">';
  // Leading empty cells from prev month
  const startDow=first.getDay();
  for(let i=0;i<startDow;i++){const pd=new Date(y,m,1-startDow+i);h+=`<div class="diary-cell other-mo"><div class="diary-cell-num">${pd.getDate()}</div></div>`;}
  for(let d=1;d<=last.getDate();d++){
    const date=new Date(y,m,d);const isToday=date.getTime()===today.getTime();
    const isCutoff=diaryIsCutoff(date);
    const isMini=!isCutoff&&diaryIsMiniCutoff(date);
    const dc=isCutoff?'cutoff':diaryDayClass(date);
    const dk=diaryDateKey(date);
    const evs=diaryEventsForKey(dk);const phol=tcPubHol(date);
    let cls=`diary-cell ${dc}${isToday?' today':''}${isMini?' minicutoff':''}`;
    h+=`<div class="${cls}" onclick="diaryOpenAdd('${dk}')">`;
    h+=`<div class="diary-cell-num">${d}</div>`;
    if(isCutoff)h+=`<div class="diary-chip cutoff-lbl">CUT-OFF</div>`;
    else if(isMini)h+=`<div class="diary-chip mini-lbl">Mini ↓</div>`;
    diaryGetSystemChips(date,isCutoff).forEach(s=>h+=`<div class="diary-chip ${s.cls}" title="${s.title}">${s.label}</div>`);
    evs.slice(0,1).forEach(ev=>{h+=`<div class="diary-chip ${ev.type||'other'}" onclick="event.stopPropagation();diaryViewEvent('${ev.id}')" title="${ev.title}">${ev.startTime?ev.startTime.slice(0,5)+' ':''}${ev.title}</div>`;});
    if(evs.length>1)h+=`<div class="diary-chip more" onclick="event.stopPropagation();diaryShowDayPanel('${dk}')">+${evs.length-1}</div>`;
    if(phol&&!isCutoff)h+=`<div style="font-size:7px;color:#dc2626;font-weight:700;margin-top:auto;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;">${phol}</div>`;
    if(phol&&isCutoff)h+=`<div style="font-size:7px;color:#fca5a5;font-weight:700;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;">${phol}</div>`;
    h+='</div>';
  }
  const lastDow=last.getDay();
  for(let i=1;i<7-lastDow;i++)h+=`<div class="diary-cell other-mo"><div class="diary-cell-num">${i}</div></div>`;
  h+='</div>';
  // Monthly notes
  const phols=Object.entries(TC_PUBHOLS_2026).filter(([k])=>parseInt(k.split('-')[1])-1===m);
  const exams=TC_EXAMS_2026.filter(e=>e.start<=last&&e.end>=first);
  if(phols.length||exams.length){
    h+='<div style="margin-top:10px;padding-top:10px;border-top:1px solid #f4f2ed;">';
    phols.forEach(([k,v])=>{h+=`<div style="font-size:11px;color:#991b1b;padding:2px 0;">🔴 ${parseInt(k.split('-')[2])} ${MONTHS[m].slice(0,3)}: ${v}</div>`;});
    exams.forEach(e=>{h+=`<div style="font-size:11px;color:#d97706;padding:2px 0;">⚠️ ${e.label} — school access limited</div>`;});
    h+='</div>';
  }
  el.innerHTML=h;
}

function _renderDiaryWeek(el,ws,DAYS3,DAYS1,MONTHS){
  const today=new Date();today.setHours(0,0,0,0);
  let h='<div class="diary-week-wrap">';
  for(let i=0;i<7;i++){
    const date=new Date(ws);date.setDate(ws.getDate()+i);
    const isToday=date.getTime()===today.getTime();
    const isCutoff=diaryIsCutoff(date);
    const isMini=!isCutoff&&diaryIsMiniCutoff(date);
    const dc=isCutoff?'cutoff':diaryDayClass(date);
    const dk=diaryDateKey(date);
    const evs=diaryEventsForKey(dk);const phol=tcPubHol(date);
    h+=`<div class="diary-week-col ${dc}${isToday?' today':''}${isMini?' minicutoff':''}">`;
    h+=`<div class="diary-week-col-hd">${DAYS3[date.getDay()].slice(0,3)}</div>`;
    h+=`<div class="diary-week-col-day">${date.getDate()}</div>`;
    if(isCutoff)h+=`<div style="font-size:8px;font-weight:700;color:#f5d98b;text-align:center;margin-bottom:3px;">CUT-OFF</div>`;
    else if(isMini)h+=`<div style="font-size:8px;font-weight:700;color:#92400e;text-align:center;margin-bottom:3px;">Mini ↓</div>`;
    if(phol)h+=`<div style="font-size:7px;color:#dc2626;font-weight:700;text-align:center;margin-bottom:3px;line-height:1.2;">${phol}</div>`;
    diaryGetSystemChips(date,isCutoff).forEach(s=>h+=`<div class="diary-week-ev diary-chip ${s.cls}" title="${s.title}">${s.label}</div>`);
    evs.forEach(ev=>{h+=`<div class="diary-week-ev diary-chip ${ev.type||'other'}" onclick="diaryViewEvent('${ev.id}')">${ev.startTime?ev.startTime.slice(0,5)+' ':''}${ev.title}</div>`;});
    h+=`<div onclick="diaryOpenAdd('${dk}')" style="text-align:center;font-size:16px;color:#d1d5db;cursor:pointer;margin-top:4px;">+</div>`;
    h+='</div>';
  }
  h+='</div>';
  el.innerHTML=h;
}

function _renderDiaryDay(el,MONTHS){
  const dk=diaryDateKey(_diaryDate);
  const evs=diaryEventsForKey(dk);
  const phol=tcPubHol(_diaryDate);const exam=tcExamLabel(_diaryDate);
  let h='';
  if(phol)h+=`<div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:8px 12px;margin-bottom:10px;font-size:12px;font-weight:600;color:#dc2626;">🔴 Public Holiday: ${phol}</div>`;
  if(exam)h+=`<div style="background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;padding:8px 12px;margin-bottom:10px;font-size:12px;font-weight:600;color:#d97706;">⚠️ ${exam} — access possible but limited</div>`;
  const isCutoffDay=diaryIsCutoff(_diaryDate);
  const sysChips=diaryGetSystemChips(_diaryDate,isCutoffDay);
  if(sysChips.length){
    sysChips.forEach(s=>{h+=`<div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:8px 12px;margin-bottom:8px;display:flex;align-items:center;gap:8px;"><span class="diary-chip ${s.cls}" style="font-size:11px;padding:3px 7px;">${s.label}</span><span style="font-size:12px;color:#6b7280;">${s.title}</span></div>`;});
  }
  if(!evs.length){
    h+=`<div style="text-align:center;color:#9ca3af;font-size:13px;padding:32px 16px;">No appointments for this day.<br><span style="font-size:11px;">Tap <b>+ Add</b> to schedule one.</span></div>`;
  } else {
    const isMgr=currentUser?.isManager||currentUser?.isOps;
    h+=evs.map(ev=>`<div class="diary-day-ev ${ev.type||'other'} ${ev.status==='tentative'?'tentative':''}" onclick="diaryViewEvent('${ev.id}')">
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;">
        <div style="min-width:0;">
          <div style="font-size:13px;font-weight:700;color:#0d1f3c;">${ev.title}</div>
          ${ev.startTime?`<div style="font-size:11px;color:#6b7280;margin-top:2px;">${ev.startTime.slice(0,5)}${ev.endTime?' – '+ev.endTime.slice(0,5):''}</div>`:''}
          ${ev.location?`<div style="font-size:11px;color:#6b7280;">📍 ${ev.location}</div>`:''}
          ${ev.notes?`<div style="font-size:11px;color:#9ca3af;margin-top:3px;">${ev.notes}</div>`:''}
          ${isMgr?`<div style="font-size:10px;color:#9ca3af;margin-top:3px;">👤 ${ev.advisorName||ev.advisorCode}</div>`:''}
        </div>
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0;">
          ${ev.status==='tentative'?'<span style="font-size:9px;font-weight:700;background:#fef3c7;color:#92400e;padding:2px 6px;border-radius:10px;">TENTATIVE</span>':''}
          <span style="font-size:9px;font-weight:700;background:#f3f4f6;color:#374151;padding:2px 6px;border-radius:10px;text-transform:uppercase;">${ev.type||'other'}</span>
        </div>
      </div>
    </div>`).join('');
  }
  el.innerHTML=h;
}

function diaryNav(dir){
  if(_diaryView==='month'){_diaryDate=new Date(_diaryDate.getFullYear(),_diaryDate.getMonth()+dir,1);}
  else if(_diaryView==='week'){_diaryDate=new Date(_diaryDate);_diaryDate.setDate(_diaryDate.getDate()+dir*7);}
  else{_diaryDate=new Date(_diaryDate);_diaryDate.setDate(_diaryDate.getDate()+dir);}
  renderDiary();
}
function diarySetView(v){_diaryView=v;renderDiary();}

function diaryOpenAdd(dateStr){
  _diaryEditId=null;
  document.getElementById('diaryAddTitle').textContent='Add Appointment';
  document.getElementById('da_title').value='';
  document.getElementById('da_date').value=dateStr||diaryDateKey(new Date());
  document.getElementById('da_start').value='08:00';
  document.getElementById('da_end').value='10:00';
  document.getElementById('da_type').value='visit';
  document.getElementById('da_loc').value='';
  document.getElementById('da_notes').value='';
  document.getElementById('da_status').value='confirmed';
  document.getElementById('diaryDeleteBtn').style.display='none';
  document.getElementById('diaryAddOverlay').style.display='flex';
}
function diaryCloseAdd(){document.getElementById('diaryAddOverlay').style.display='none';_diaryEditId=null;}

function diaryViewEvent(id){
  const ev=diaryGetEvents().find(e=>e.id===id);if(!ev)return;
  const canEdit=currentUser?.isManager||currentUser?.isOps||ev.advisorCode===currentUser?.code;
  if(!canEdit)return;
  _diaryEditId=id;
  document.getElementById('diaryAddTitle').textContent='Edit Appointment';
  document.getElementById('da_title').value=ev.title||'';
  document.getElementById('da_date').value=ev.date||'';
  document.getElementById('da_start').value=ev.startTime||'';
  document.getElementById('da_end').value=ev.endTime||'';
  document.getElementById('da_type').value=ev.type||'visit';
  document.getElementById('da_loc').value=ev.location||'';
  document.getElementById('da_notes').value=ev.notes||'';
  document.getElementById('da_status').value=ev.status||'confirmed';
  document.getElementById('diaryDeleteBtn').style.display='inline-block';
  document.getElementById('diaryAddOverlay').style.display='flex';
}

function diarySaveAdd(){
  const v=id=>{const el=document.getElementById(id);return el?el.value.trim():'';};
  const title=v('da_title'),date=v('da_date');
  if(!title)return showAlert('Please enter a title.','error');
  if(!date)return showAlert('Please enter a date.','error');
  const events=diaryGetEvents();
  if(_diaryEditId){
    const idx=events.findIndex(e=>e.id===_diaryEditId);
    if(idx>=0)events[idx]={...events[idx],title,date,startTime:v('da_start'),endTime:v('da_end'),type:v('da_type'),location:v('da_loc'),notes:v('da_notes'),status:v('da_status')};
    if(window.FB_READY)window.FB.saveCalEvent(_diaryEditId,events[idx]).catch(()=>{});
  } else {
    const id=Date.now()+'_'+Math.random().toString(36).slice(2);
    const newEv={id,advisorCode:currentUser.code,advisorName:currentUser.name,title,date,startTime:v('da_start'),endTime:v('da_end'),type:v('da_type'),location:v('da_loc'),notes:v('da_notes'),status:v('da_status'),reminderSent:[]};
    events.push(newEv);
    if(window.FB_READY)window.FB.saveCalEvent(id,newEv).catch(()=>{});
  }
  diarySaveEvents(events);
  diaryCloseAdd();
  const parts=date.split('-').map(Number);
  _diaryDate=new Date(parts[0],parts[1]-1,parts[2]);
  renderDiary();
  showAlert('Appointment saved.','success');
}

function diaryDeleteFromModal(){
  if(!_diaryEditId||!confirm('Delete this appointment?'))return;
  const events=diaryGetEvents().filter(e=>e.id!==_diaryEditId);
  diarySaveEvents(events);
  if(window.FB_READY)window.FB.deleteCalEvent(_diaryEditId).catch(()=>{});
  diaryCloseAdd();renderDiary();
  showAlert('Appointment deleted.','success');
}

function diaryCheckReminders(){
  if(!currentUser||!window.FB_READY)return;
  const events=diaryGetEvents().filter(e=>e.advisorCode===currentUser.code);
  const today=new Date();today.setHours(0,0,0,0);
  events.forEach(ev=>{
    const evDate=diaryParseKey(ev.date);
    if(evDate<today)return;
    const daysAway=Math.round((evDate-today)/(86400000));
    const sentKey='tl_drem_'+ev.id;
    const sent=JSON.parse(localStorage.getItem(sentKey)||'[]');
    let level=null;
    if(daysAway===0)level='today';
    else if(daysAway===1)level='tomorrow';
    else if(daysAway<=3&&!sent.includes('3days'))level='3days';
    if(level&&!sent.includes(level)){
      const prefix={today:'TODAY',tomorrow:'TOMORROW','3days':'in 3 days'};
      window.FB.sendInbox({
        to:currentUser.code,from:'SYSTEM',fromName:'Diary Reminder',
        title:`🗓️ Appointment ${prefix[level]}: "${ev.title}"`,
        body:`${ev.startTime?ev.startTime+' · ':''}${ev.location||''}${ev.notes?'\n'+ev.notes:''}`.trim(),
        type:'reminder'
      }).catch(()=>{});
      sent.push(level);localStorage.setItem(sentKey,JSON.stringify(sent));
    }
  });
}

function renderTermCal(){
  _diaryDate=new Date();
  renderDiary();
  diaryCheckReminders();
  if(window.FB_READY){
    window.FB.getAllCalEvents().then(fbEvs=>{
      const local=diaryGetEvents();const localIds=new Set(local.map(e=>e.id));
      const merged=[...local];fbEvs.forEach(e=>{if(!localIds.has(e.id))merged.push(e);});
      diarySaveEvents(merged);renderDiary();
    }).catch(()=>{});
  }
}
const _APPT_STATUSES=[
  {v:'confirmed', label:'Confirmed', color:'#16a34a', bg:'#dcfce7'},
  {v:'done',      label:'Done',      color:'#1d4ed8', bg:'#dbeafe'},
  {v:'postponed', label:'Postponed', color:'#d97706', bg:'#fef3c7'},
  {v:'revisit',   label:'Revisit',   color:'#7c3aed', bg:'#ede9fe'},
  {v:'tentative', label:'Tentative', color:'#9ca3af', bg:'#f3f4f6'},
];
function diaryShowDayPanel(dk){
  // Remove old panel if any
  document.getElementById('diaryDayPanel')?.remove();
  const isOps=currentUser?.isManager||currentUser?.isOps;
  // All visible events for this day (already filtered by advisor in diaryEventsForKey)
  const evs=diaryEventsForKey(dk);
  if(!evs.length)return;
  const [y,m,d]=dk.split('-');
  const dateLabel=`${parseInt(d)} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][parseInt(m)-1]} ${y}`;
  const panel=document.createElement('div');
  panel.id='diaryDayPanel';
  panel.style.cssText='position:fixed;inset:0;z-index:9100;display:flex;align-items:flex-end;background:rgba(0,0,0,.45);';
  const inner=document.createElement('div');
  inner.style.cssText='background:#fff;width:100%;max-height:80vh;border-radius:20px 20px 0 0;overflow-y:auto;padding:0 0 32px;';
  const statusOpts=_APPT_STATUSES.map(s=>`<option value="${s.v}">${s.label}</option>`).join('');
  inner.innerHTML=`
    <div style="position:sticky;top:0;background:#fff;padding:14px 16px 10px;border-bottom:1px solid #f4f2ed;display:flex;align-items:center;justify-content:space-between;z-index:1;">
      <div>
        <div style="font-size:11px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.5px;">Appointments</div>
        <div style="font-size:16px;font-weight:700;color:#0d1f3c;">${dateLabel}</div>
      </div>
      <button onclick="document.getElementById('diaryDayPanel').remove()" style="background:none;border:none;font-size:22px;color:#9ca3af;cursor:pointer;line-height:1;">✕</button>
    </div>
    <div style="padding:10px 14px;display:flex;flex-direction:column;gap:10px;">
      ${evs.map(ev=>{
        const st=_APPT_STATUSES.find(s=>s.v===(ev.status||'confirmed'))||_APPT_STATUSES[0];
        const timeStr=(ev.startTime?ev.startTime.slice(0,5):'')+(ev.endTime?' – '+ev.endTime.slice(0,5):'');
        return`<div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:12px;padding:12px 14px;">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:8px;">
            <div>
              <div style="font-size:14px;font-weight:700;color:#0d1f3c;">${ev.title}</div>
              ${timeStr?`<div style="font-size:11px;color:#6b7280;margin-top:2px;">⏰ ${timeStr}</div>`:''}
              ${ev.location?`<div style="font-size:11px;color:#6b7280;">📍 ${ev.location}</div>`:''}
              ${isOps&&ev.advisorName?`<div style="font-size:11px;color:#6b7280;">👤 ${ev.advisorName}</div>`:''}
            </div>
            <span style="font-size:10px;font-weight:700;padding:3px 8px;border-radius:20px;background:${st.bg};color:${st.color};white-space:nowrap;">${st.label}</span>
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:6px;">
            ${_APPT_STATUSES.map(s=>`<label style="display:flex;align-items:center;gap:4px;cursor:pointer;font-size:11px;font-weight:600;padding:4px 9px;border-radius:20px;border:1.5px solid ${(ev.status||'confirmed')===s.v?s.color:'#e5e7eb'};background:${(ev.status||'confirmed')===s.v?s.bg:'#fff'};color:${(ev.status||'confirmed')===s.v?s.color:'#6b7280'};transition:all .15s;">
              <input type="radio" name="apst_${ev.id}" value="${s.v}" ${(ev.status||'confirmed')===s.v?'checked':''} onchange="diaryUpdateEventStatus('${ev.id}',this.value)" style="display:none;"/>
              ${s.label}
            </label>`).join('')}
          </div>
        </div>`;
      }).join('')}
    </div>`;
  panel.appendChild(inner);
  panel.addEventListener('click',e=>{if(e.target===panel)panel.remove();});
  document.body.appendChild(panel);
}
function diaryUpdateEventStatus(id,status){
  const events=diaryGetEvents();
  const idx=events.findIndex(e=>e.id===id);
  if(idx<0)return;
  events[idx].status=status;
  diarySaveEvents(events);
  if(window.FB_READY)window.FB.saveCalEvent(id,events[idx]).catch(()=>{});
  // Refresh radio button styling in the panel
  document.querySelectorAll(`[name="apst_${id}"]`).forEach(r=>{
    const lbl=r.closest('label');
    const s=_APPT_STATUSES.find(x=>x.v===r.value);
    if(!s||!lbl)return;
    const active=r.value===status;
    lbl.style.borderColor=active?s.color:'#e5e7eb';
    lbl.style.background=active?s.bg:'#fff';
    lbl.style.color=active?s.color:'#6b7280';
  });
  // Update badge in the panel
  const row=document.querySelector(`[name="apst_${id}"]`)?.closest('div[style*="background:#f9fafb"]');
  if(row){const badge=row.querySelector('span[style*="border-radius:20px"]');const st=_APPT_STATUSES.find(s=>s.v===status);if(badge&&st){badge.style.background=st.bg;badge.style.color=st.color;badge.textContent=st.label;}}
}
// ── END DIARY / PLANNER ───────────────────────────────────────────────────────

// ── NTU & PERSISTENCY DASHBOARD ─────────────────────────────────────────────
function getNTUCases(){try{return JSON.parse(localStorage.getItem('tl_ntu_cases')||'[]');}catch(e){return[];}}
function saveNTUCases(d){localStorage.setItem('tl_ntu_cases',JSON.stringify(d));}
function ntuLogCase(){
  const advisorSel=document.getElementById('ntu-advisor');
  const advCode=advisorSel?advisorSel.value:'';
  const advName=advisorSel&&advisorSel.selectedIndex>=0?advisorSel.options[advisorSel.selectedIndex].text:'';
  const type=document.getElementById('ntu-type').value;
  const client=document.getElementById('ntu-client').value.trim();
  const month=document.getElementById('ntu-month').value;
  if(!advCode||!client)return showAlert('Please select an advisor and enter client name.','error');
  const cases=getNTUCases();
  cases.push({id:Date.now()+'_'+Math.random().toString(36).slice(2),advisorCode:advCode,advisorName:advName,type,client,month,loggedAt:new Date().toISOString()});
  saveNTUCases(cases);
  document.getElementById('ntu-client').value='';
  renderNTUDash();
  showAlert('Case logged.','success');
}
function ntuDeleteCase(id){
  saveNTUCases(getNTUCases().filter(x=>x.id!==id));renderNTUDash();
}
function renderNTUDash(){
  const el=document.getElementById('ntuDashboard');if(!el)return;
  // Populate advisor dropdown
  const sel=document.getElementById('ntu-advisor');
  if(sel){
    const users=getUsers();
    const advisors=Object.values(users).filter(u=>!u.isOps&&!u.isManager).sort((a,b)=>a.name.localeCompare(b.name));
    sel.innerHTML='<option value="">Select advisor...</option>'+advisors.map(a=>`<option value="${a.code}">${a.name}</option>`).join('');
  }
  const allCCases=getCCases();
  const ntuCases=getNTUCases();
  const users=getUsers();
  const advisors=Object.values(users).filter(u=>!u.isOps&&!u.isManager);
  if(!advisors.length){el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:2rem;">No advisors found.</div>';return;}
  el.innerHTML=advisors.map(adv=>{
    const written=allCCases.filter(c=>c.advisorCode===adv.code).length;
    const ntu=ntuCases.filter(c=>c.advisorCode===adv.code&&c.type==='ntu').length;
    const lapsed=ntuCases.filter(c=>c.advisorCode===adv.code&&c.type==='lapse').length;
    const ntuPct=written>0?Math.round(ntu/written*100):0;
    const persistPct=written>0?Math.round((written-lapsed)/Math.max(written,1)*100):100;
    const ntuWarn=ntuPct>15;const persistWarn=persistPct<65;
    const ntuCol=ntuWarn?'#dc2626':'#16a34a';const persistCol=persistWarn?'#dc2626':'#16a34a';
    const recentNTU=ntuCases.filter(c=>c.advisorCode===adv.code).slice(-3).reverse();
    return`<div class="ntu-adv-card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
        <div style="font-size:14px;font-weight:700;color:#0d1f3c;">${adv.name}</div>
        <div style="display:flex;gap:6px;">
          ${ntuWarn?'<div style="background:#fef2f2;color:#991b1b;font-size:10px;font-weight:700;padding:3px 8px;border-radius:20px;">⚠️ NTU HIGH</div>':''}
          ${persistWarn?'<div style="background:#fef2f2;color:#991b1b;font-size:10px;font-weight:700;padding:3px 8px;border-radius:20px;">⚠️ PERSIST LOW</div>':''}
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:12px;">
        <div style="text-align:center;"><div style="font-size:18px;font-weight:800;color:#0d1f3c;">${written}</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;">Cases written</div></div>
        <div style="text-align:center;"><div style="font-size:18px;font-weight:800;color:${ntuCol};">${ntuPct}%</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;">NTU rate</div>
          <div class="ntu-bar-wrap"><div class="ntu-bar" style="width:${Math.min(ntuPct,100)}%;background:${ntuCol};"></div></div>
          <div style="font-size:9px;color:#9ca3af;margin-top:2px;">Target: below 15%</div>
        </div>
        <div style="text-align:center;"><div style="font-size:18px;font-weight:800;color:${persistCol};">${persistPct}%</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;">Persistency</div>
          <div class="ntu-bar-wrap"><div class="ntu-bar" style="width:${persistPct}%;background:${persistCol};"></div></div>
          <div style="font-size:9px;color:#9ca3af;margin-top:2px;">Target: above 65%</div>
        </div>
      </div>
      ${recentNTU.length?`<div style="border-top:1px solid #f4f2ed;padding-top:8px;"><div style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">Recent NTU / lapses</div>${recentNTU.map(c=>`<div style="display:flex;align-items:center;justify-content:space-between;padding:4px 0;"><div style="font-size:12px;font-weight:600;color:#0d1f3c;">${c.client} <span style="font-size:10px;color:${c.type==='ntu'?'#dc2626':'#d97706'};font-weight:700;">(${c.type==='ntu'?'NTU':'Lapsed'})</span></div><div style="display:flex;align-items:center;gap:6px;"><div style="font-size:10px;color:#9ca3af;">${c.month}</div><button onclick="ntuDeleteCase('${c.id}')" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:12px;padding:2px;">✕</button></div></div>`).join('')}</div>`:''
    }</div>`;
  }).join('');
}
// ── END NTU & PERSISTENCY ────────────────────────────────────────────────────

// ── ROA COMPLIANCE CHECKLIST ─────────────────────────────────────────────────
function roaChecklistToggle(){
  const body=document.getElementById('roaChecklistBody');
  const chev=document.getElementById('roaChecklistChev');
  if(!body)return;
  const open=body.style.display!=='none';
  body.style.display=open?'none':'block';
  if(chev)chev.style.transform=open?'':'rotate(180deg)';
}
document.addEventListener('change',function(e){
  if(e.target&&e.target.classList.contains('roa-cl-cb')){
    const cbs=document.querySelectorAll('.roa-cl-cb');
    const done=[...cbs].filter(c=>c.checked).length;
    const total=cbs.length;
    const st=document.getElementById('roaClStatus');
    if(st){
      if(done===total)st.innerHTML='<span style="color:#16a34a;">✓ All '+total+' items checked — ROA is compliance-ready</span>';
      else st.innerHTML=`<span style="color:#d97706;">${done}/${total} items checked</span>`;
    }
  }
});
// ── END ROA COMPLIANCE CHECKLIST ─────────────────────────────────────────────

/* ── More dropdown helpers ── */
function openMoreDropdown(){
  document.getElementById('navMoreOverlay').classList.add('open');
  document.getElementById('navMoreDropdown').classList.add('open');
  document.getElementById('navMoreBtn').classList.add('active');
}
function closeMoreDropdown(){
  const o=document.getElementById('navMoreOverlay');
  const d=document.getElementById('navMoreDropdown');
  if(o)o.classList.remove('open');
  if(d)d.classList.remove('open');
  // Don't remove active from btn here — showPage handles it
}
function toggleMoreDropdown(){
  const d=document.getElementById('navMoreDropdown');
  if(d&&d.classList.contains('open'))closeMoreDropdown();
  else openMoreDropdown();
}
function moreShowPage(p){closeMoreDropdown();showPage(p);}

// ── DAILY BY REGION ──────────────────────────────────────────────────────────
const DR={allRows:[],filtered:[],page:1,perPage:100,sortCol:null,sortDir:1,filters:{team:'all',status:'all',advisor:'all',q:''}};

function initDailyRegion(){
  const el=document.getElementById('dailyRegionContent');
  if(!el)return;
  if(DR.allRows.length){renderDailyRegion();return;}
  el.innerHTML=`
    <div style="text-align:center;padding:50px 20px;">
      <div style="font-size:52px;margin-bottom:14px;">📈</div>
      <h3 style="margin:0 0 6px;color:#0d1f3c;font-size:16px;">Daily By Region</h3>
      <p style="color:#6b7280;font-size:13px;margin:0 0 22px;line-height:1.5;">Upload the 2-Year Excel file — Lions &amp; Mavericks data will load automatically.</p>
      <input type="file" id="drFileInput" accept=".xlsx,.xls" style="display:none;" onchange="drFileSelected(this)"/>
      <button onclick="document.getElementById('drFileInput').click()" style="background:#0d1f3c;color:#fff;border:none;border-radius:12px;padding:13px 28px;font-size:14px;font-weight:700;cursor:pointer;box-shadow:0 4px 14px rgba(13,31,60,.25);">📂 Upload Excel File</button>
      <p style="color:#9ca3af;font-size:11px;margin-top:12px;">2 Year file (.xlsx)</p>
    </div>`;
}

async function drFileSelected(input){
  if(!input.files||!input.files[0])return;
  const el=document.getElementById('dailyRegionContent');
  if(el)el.innerHTML=`<div style="text-align:center;padding:50px 20px;"><div style="font-size:40px;margin-bottom:12px;">⏳</div><p style="color:#6b7280;font-size:13px;font-weight:600;">Loading &amp; filtering data…</p><p style="color:#9ca3af;font-size:11px;margin-top:4px;">This may take a few seconds</p></div>`;
  if(!window.XLSX){
    await new Promise((res,rej)=>{
      const s=document.createElement('script');
      s.src='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
      s.onload=res;s.onerror=rej;document.head.appendChild(s);
    });
  }
  try{
    const buf=await input.files[0].arrayBuffer();
    const wb=XLSX.read(buf,{type:'array',cellDates:true});
    const ws=wb.Sheets[wb.SheetNames[0]];
    const raw=XLSX.utils.sheet_to_json(ws,{header:1,defval:null,raw:false});
    const headers=(raw[2]||[]).map(h=>String(h||'').trim());
    const rows=[];
    for(let i=3;i<raw.length;i++){
      const row=raw[i];
      if(!row||row.length<6)continue;
      const teamIdx=headers.indexOf('Sales Team');
      const team=String(row[teamIdx]||'').trim();
      if(!team.toLowerCase().includes('lion')&&!team.toLowerCase().includes('maverick'))continue;
      const obj={};
      headers.forEach((h,idx)=>{obj[h]=row[idx];});
      rows.push(obj);
    }
    DR.allRows=rows;DR.filtered=[...rows];DR.page=1;
    renderDailyRegion();
  }catch(e){
    console.error('DR parse error:',e);
    if(el)el.innerHTML=`<div style="text-align:center;padding:40px;color:#dc2626;"><p>Could not read file. Please use the 2-Year .xlsx export.</p><button onclick="initDailyRegion()" style="margin-top:10px;padding:8px 16px;border:none;background:#0d1f3c;color:#fff;border-radius:8px;cursor:pointer;">Try Again</button></div>`;
  }
}

function drApplyFilters(){
  const{team,status,advisor,q}=DR.filters;
  const ql=q.toLowerCase();
  DR.filtered=DR.allRows.filter(r=>{
    const t=String(r['Sales Team']||'').toLowerCase();
    if(team==='lions'&&!t.includes('lion'))return false;
    if(team==='mavericks'&&!t.includes('maverick'))return false;
    const s=String(r['Policy Status']||'').trim();
    if(status!=='all'&&s!==status)return false;
    if(advisor!=='all'&&String(r['Rep Name']||'').trim()!==advisor)return false;
    if(ql){
      const name=String(r['Main Life']||r['Payer']||'').toLowerCase();
      const pol=String(r['Policy No']||'').toLowerCase();
      const emp=String(r['PayPoint Name']||'').toLowerCase();
      const rep=String(r['Rep Name']||'').toLowerCase();
      if(!name.includes(ql)&&!pol.includes(ql)&&!emp.includes(ql)&&!rep.includes(ql))return false;
    }
    return true;
  });
  if(DR.sortCol){
    DR.filtered.sort((a,b)=>{
      const av=String(a[DR.sortCol]||'').toLowerCase();
      const bv=String(b[DR.sortCol]||'').toLowerCase();
      return av<bv?-DR.sortDir:av>bv?DR.sortDir:0;
    });
  }
  DR.page=1;
}
function drSort(col){
  if(DR.sortCol===col){DR.sortDir*=-1;}else{DR.sortCol=col;DR.sortDir=1;}
  drApplyFilters();renderDailyRegion();
}

function drFmtDate(v){
  if(!v)return'—';
  const s=String(v);
  if(s.startsWith('1901')||s.startsWith('1900')||s==='null')return'—';
  if(s.length>=10)return s.substring(0,10);
  return s;
}
function drFmtMoney(v){
  const n=parseFloat(String(v).replace(/[^0-9.-]/g,''));
  if(isNaN(n))return'—';
  return'R '+n.toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function drStatusBadge(s){
  const map={'In-Force':'#059669','Pending In-Force':'#0284c7','Lapsed':'#ea580c','Cancelled':'#dc2626','Not Taken Up':'#6b7280','Out-of-Force':'#7c3aed','Surrendered':'#92400e','Paid Up':'#374151'};
  const col=map[s]||'#9ca3af';
  return`<span style="background:${col};color:#fff;padding:2px 7px;border-radius:10px;font-size:10px;font-weight:700;white-space:nowrap;">${s||'—'}</span>`;
}

function renderDailyRegion(){
  const el=document.getElementById('dailyRegionContent');
  if(!el)return;
  const rows=DR.filtered;
  // KPIs
  let totalPrem=0,inForce=0,stopOrders=0;
  const clients=new Set();
  rows.forEach(r=>{
    const p=parseFloat(String(r['Monthly Prem']||'0').replace(/[^0-9.-]/g,''))||0;
    totalPrem+=p;
    if(String(r['Policy Status']||'')==='In-Force')inForce++;
    const bt=String(r['Bill Type']||r['Pol OBill Type']||'').toLowerCase();
    if(bt.includes('stop order')||bt.includes('persal'))stopOrders++;
    const id=String(r['Main Life ID No']||r['Payer  ID No']||r['Payer ID No']||'').trim();
    if(id&&id.length>5)clients.add(id);
  });
  const stopPct=rows.length?((stopOrders/rows.length)*100).toFixed(1):'0.0';
  const lionsCount=rows.filter(r=>String(r['Sales Team']||'').toLowerCase().includes('lion')).length;
  const mavCount=rows.length-lionsCount;
  // Pagination
  const total=rows.length,pages=Math.max(1,Math.ceil(total/DR.perPage));
  DR.page=Math.min(DR.page,pages);
  const start=(DR.page-1)*DR.perPage;
  const pageRows=rows.slice(start,start+DR.perPage);

  const kpi=(label,val,sub)=>`<div style="background:#fff;border-radius:10px;padding:10px 12px;box-shadow:0 1px 4px rgba(0,0,0,.08);flex:1;min-width:100px;"><div style="font-size:9px;color:#6b7280;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:3px;">${label}</div><div style="font-size:14px;font-weight:800;color:#0d1f3c;line-height:1.2;">${val}</div>${sub?`<div style="font-size:9px;color:#9ca3af;margin-top:1px;">${sub}</div>`:''}</div>`;

  const tableRows=pageRows.map((r,i)=>{
    const team=String(r['Sales Team']||'').trim();
    const isLion=team.toLowerCase().includes('lion');
    const status=String(r['Policy Status']||'').trim();
    const repFull=String(r['Rep Name']||'').trim();
    const repShort=repFull.split(' ').filter(Boolean).slice(-2).join(' ');
    const employer=String(r['PayPoint Name']||'').trim();
    const product=String(r['Product']||'').replace('Sanlam ','').replace('Enhanced Priority Funeral Plans','EPFP').replace('All In One Funeral Plan','AIO FP').replace('Invest to Graduate Plan','I2G').replace('Funeral Plan','FP').replace('Priority Funeral','PFP');
    const bt=String(r['Bill Type']||r['Pol OBill Type']||'—').replace('Stop Order','SO').replace('Debit Order','DO').replace('Advanceable','Adv').replace('As And When','AAW');
    const pers=parseFloat(r['Rep Pers']);
    return`<tr style="background:${i%2?'#f9fafb':'#fff'};border-bottom:1px solid #f0f0f0;">
      <td style="padding:6px 5px;color:#374151;font-size:10px;max-width:70px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${repFull}">${repShort}</td>
      <td style="padding:6px 5px;font-family:monospace;color:#0d1f3c;font-size:10px;white-space:nowrap;">${r['Policy No']||'—'}</td>
      <td style="padding:6px 5px;font-weight:600;color:#111;font-size:11px;max-width:110px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${String(r['Main Life']||r['Payer']||'').trim()}">${String(r['Main Life']||r['Payer']||'').trim()}</td>
      <td style="padding:6px 5px;color:#6b7280;font-size:10px;max-width:100px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${employer}">${employer||'—'}</td>
      <td style="padding:6px 5px;text-align:right;font-weight:700;color:#059669;font-size:11px;white-space:nowrap;">${drFmtMoney(r['Monthly Prem'])}</td>
      <td style="padding:6px 5px;text-align:center;color:#6b7280;font-size:10px;white-space:nowrap;">${bt}</td>
      <td style="padding:6px 5px;text-align:center;color:#6b7280;font-size:10px;white-space:nowrap;">${drFmtDate(r['Pol Signed Date'])}</td>
      <td style="padding:6px 5px;text-align:center;color:#6b7280;font-size:10px;white-space:nowrap;">${drFmtDate(r['Issue Date'])}</td>
      <td style="padding:6px 5px;text-align:center;color:#6b7280;font-size:10px;white-space:nowrap;">${drFmtDate(r['Pay To Date'])}</td>
      <td style="padding:6px 5px;text-align:center;">${drStatusBadge(status)}</td>
      <td style="padding:6px 5px;color:#6b7280;font-size:10px;max-width:90px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${r['Product']||''}">${product}</td>
      <td style="padding:6px 5px;text-align:center;"><span style="background:${isLion?'#fef3c7':'#ede9fe'};color:${isLion?'#92400e':'#5b21b6'};padding:2px 6px;border-radius:8px;font-size:9px;font-weight:700;">${isLion?'LIONS':'MAV'}</span></td>
      <td style="padding:6px 5px;text-align:center;color:#374151;font-size:10px;">${isNaN(pers)?'—':pers.toFixed(1)+'%'}</td>
    </tr>`;
  }).join('');

  el.innerHTML=`
    <div style="display:flex;flex-wrap:wrap;gap:7px;margin-bottom:12px;">
      ${kpi('Monthly Prem',drFmtMoney(totalPrem))}
      ${kpi('Annual Prem',drFmtMoney(totalPrem*12),'× 12')}
      ${kpi('Records',total.toLocaleString())}
      ${kpi('In-Force',inForce.toLocaleString())}
      ${kpi('Stop Order',stopPct+'%')}
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px;align-items:center;">
      <div style="font-size:11px;color:#6b7280;background:#f4f2ed;border-radius:8px;padding:4px 10px;">
        🦁 Lions: <strong>${lionsCount.toLocaleString()}</strong> &nbsp;|&nbsp; 🟣 Mavericks: <strong>${mavCount.toLocaleString()}</strong>
      </div>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px;align-items:center;">
      <select onchange="DR.filters.team=this.value;DR.filters.advisor='all';drApplyFilters();renderDailyRegion()" style="padding:6px 8px;border:1px solid #e5e7eb;border-radius:8px;font-size:12px;background:#fff;">
        <option value="all"${DR.filters.team==='all'?' selected':''}>All Teams</option>
        <option value="lions"${DR.filters.team==='lions'?' selected':''}>🦁 Lions</option>
        <option value="mavericks"${DR.filters.team==='mavericks'?' selected':''}>🟣 Mavericks</option>
      </select>
      <select onchange="DR.filters.advisor=this.value;drApplyFilters();renderDailyRegion()" style="padding:6px 8px;border:1px solid #e5e7eb;border-radius:8px;font-size:12px;background:#fff;max-width:160px;">
        <option value="all"${DR.filters.advisor==='all'?' selected':''}>All Advisors</option>
        ${[...new Set(DR.allRows.filter(r=>{const t=String(r['Sales Team']||'').toLowerCase();return DR.filters.team==='all'||(DR.filters.team==='lions'&&t.includes('lion'))||(DR.filters.team==='mavericks'&&t.includes('maverick'));}).map(r=>String(r['Rep Name']||'').trim()).filter(Boolean))].sort().map(n=>`<option value="${n.replace(/"/g,'&quot;')}"${DR.filters.advisor===n?' selected':''}>${n}</option>`).join('')}
      </select>
      <select onchange="DR.filters.status=this.value;drApplyFilters();renderDailyRegion()" style="padding:6px 8px;border:1px solid #e5e7eb;border-radius:8px;font-size:12px;background:#fff;">
        <option value="all"${DR.filters.status==='all'?' selected':''}>All Statuses</option>
        <option value="In-Force"${DR.filters.status==='In-Force'?' selected':''}>In-Force</option>
        <option value="Pending In-Force"${DR.filters.status==='Pending In-Force'?' selected':''}>Pending In-Force</option>
        <option value="Lapsed"${DR.filters.status==='Lapsed'?' selected':''}>Lapsed</option>
        <option value="Cancelled"${DR.filters.status==='Cancelled'?' selected':''}>Cancelled</option>
        <option value="Not Taken Up"${DR.filters.status==='Not Taken Up'?' selected':''}>Not Taken Up</option>
        <option value="Out-of-Force"${DR.filters.status==='Out-of-Force'?' selected':''}>Out-of-Force</option>
      </select>
      <input placeholder="Search name / policy / employer…" value="${DR.filters.q.replace(/"/g,'&quot;')}" oninput="DR.filters.q=this.value;drApplyFilters();renderDailyRegion()" style="flex:1;min-width:140px;padding:6px 10px;border:1px solid #e5e7eb;border-radius:8px;font-size:12px;"/>
      <button onclick="DR.allRows=[];DR.filtered=[];DR.page=1;DR.sortCol=null;DR.sortDir=1;DR.filters={team:'all',status:'all',advisor:'all',q:''};initDailyRegion()" style="padding:6px 10px;background:#f4f2ed;border:1px solid #e5e7eb;border-radius:8px;font-size:11px;font-weight:600;cursor:pointer;color:#374151;white-space:nowrap;">↑ New File</button>
    </div>
    <div style="overflow-x:auto;border-radius:10px;border:1px solid #e5e7eb;margin-bottom:10px;">
      <table style="width:100%;border-collapse:collapse;min-width:860px;">
        <thead>
          <tr style="background:#0d1f3c;color:#fff;font-size:10px;">
            ${[['Rep Name','Rep'],['Policy No','Policy No'],['Main Life','Client Name'],['PayPoint Name','Employer'],['Monthly Prem','Monthly Prem'],['Bill Type','Bill Type'],['Pol Signed Date','Signed'],['Issue Date','Issue Date'],['Pay To Date','Pay To'],['Policy Status','Status'],['Product','Product'],['Sales Team','Team'],['Rep Pers','Pers%']].map(([col,label])=>{
              const active=DR.sortCol===col;
              const arrow=active?(DR.sortDir===1?' ↑':' ↓'):'';
              const align=['Monthly Prem','Rep Pers'].includes(col)?'right':['Policy No','Pol Signed Date','Issue Date','Pay To Date','Policy Status','Sales Team'].includes(col)?'center':'left';
              return`<th onclick="drSort('${col}')" style="padding:8px 5px;text-align:${align};font-weight:700;cursor:pointer;white-space:nowrap;user-select:none;${active?'background:rgba(255,255,255,.12);':''}">${label}${arrow}</th>`;
            }).join('')}
          </tr>
        </thead>
        <tbody>${tableRows}</tbody>
      </table>
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px;padding-bottom:16px;">
      <div style="font-size:11px;color:#6b7280;">Showing ${(start+1).toLocaleString()}–${Math.min(start+DR.perPage,total).toLocaleString()} of <strong>${total.toLocaleString()}</strong> records</div>
      <div style="display:flex;gap:5px;align-items:center;">
        <button onclick="DR.page=1;renderDailyRegion()" ${DR.page===1?'disabled':''} style="padding:5px 9px;border:1px solid #e5e7eb;border-radius:6px;background:${DR.page===1?'#f3f4f6':'#fff'};font-size:12px;cursor:pointer;">«</button>
        <button onclick="DR.page=Math.max(1,DR.page-1);renderDailyRegion()" ${DR.page===1?'disabled':''} style="padding:5px 10px;border:1px solid #e5e7eb;border-radius:6px;background:${DR.page===1?'#f3f4f6':'#fff'};font-size:12px;cursor:pointer;">← Prev</button>
        <span style="padding:5px 10px;font-size:12px;color:#374151;white-space:nowrap;">Page ${DR.page} / ${pages}</span>
        <button onclick="DR.page=Math.min(${pages},DR.page+1);renderDailyRegion()" ${DR.page===pages?'disabled':''} style="padding:5px 10px;border:1px solid #e5e7eb;border-radius:6px;background:${DR.page===pages?'#f3f4f6':'#fff'};font-size:12px;cursor:pointer;">Next →</button>
        <button onclick="DR.page=${pages};renderDailyRegion()" ${DR.page===pages?'disabled':''} style="padding:5px 9px;border:1px solid #e5e7eb;border-radius:6px;background:${DR.page===pages?'#f3f4f6':'#fff'};font-size:12px;cursor:pointer;">»</button>
      </div>
    </div>`;
}
// ── END DAILY BY REGION ───────────────────────────────────────────────────────

// ─────────────────────────────────────────────
// FSP FORMS SYSTEM
// ─────────────────────────────────────────────

const FORMS_CAT = [
  { fsp:'Universal Forms', color:'#374151', forms:[
    { id:'cancel_letter',   name:'Cancellation Letter',        desc:'Multi-insurer multi-policy cancellation' },
    { id:'refund_letter',   name:'Refund Request Letter',      desc:'Request premium refund after cancellation' },
    { id:'precan_reversal', name:'Pre-Cancellation Reversal',  desc:'Withdraw a previous cancellation request' },
  ]},
  { fsp:'Regulatory', color:'#7c3aed', forms:[
    { id:'repl_disclosure', name:'Replacement Disclosure & Client Acknowledgment', desc:'Client confirms voluntary replacement — adviser + client sign' },
  ]},
  // FSP-specific forms — hidden for now
  { fsp:'_Workers Life', color:'#166534', forms:[
    { id:'wl_cancel',  name:'Cancellation Request',      desc:'30-day written notice to cancel policy' },
    { id:'wl_payment', name:'Payment Mandate (Debit Order)', desc:'Authorise monthly premium collection' },
  ]},
  { fsp:'_Assupol', color:'#1e40af', forms:[
    { id:'assupol_debit', name:'Debit Order Authorization', desc:'Authorise premium debit order per policy' },
  ]},
  { fsp:'_Sanlam Sky', color:'#003087', forms:[
    { id:'sansky_cancel',  name:'Cancellation Letter',         desc:'Multi-policy cancellation request' },
    { id:'sansky_banking', name:'Banking Details Change',      desc:'Update debit order bank account' },
  ]},
  { fsp:'_Sanlam Life', color:'#003087', forms:[
    { id:'sanlife_cancel', name:'Cancellation Letter', desc:'Sanlam Life policy cancellation request' },
  ]},
  { fsp:'_SAPS', color:'#6d28d9', forms:[
    { id:'saps_cancel', name:'SAPS Cancellation Form', desc:'SAPS member policy cancellation notice' },
  ]},
  { fsp:'_Metropolitan', color:'#c2185b', forms:[
    { id:'metro_debit',   name:'Bank Debit Order',           desc:'Arrange policy payment by debit order' },
    { id:'metro_paidup',  name:'Application to Make Policy Paid-Up', desc:'Convert policy to paid-up status' },
    { id:'metro_surrender', name:'Full Surrender Application', desc:'Surrender policy and receive surrender value' },
  ]},
  { fsp:'_Hollard Specialist Life', color:'#b45309', forms:[
    { id:'hsl_debit',    name:'Debit Order Authorisation (IL020)', desc:'Authorise monthly premium debit order' },
    { id:'hsl_surrender', name:'Application to Surrender (CS003)', desc:'Full or partial policy surrender' },
  ]},
  { fsp:'_AVBOB', color:'#065f46', forms:[
    { id:'avbob_debit',    name:'Debit Order Authorisation', desc:'Authorise premium and debt debit order' },
    { id:'avbob_surrender', name:'Surrender Application',    desc:'Apply for surrender of policy / savings plan' },
  ]},
];

function renderFormsPage(){
  const q=(document.getElementById('formsSearch')?.value||'').toLowerCase().trim();
  const el=document.getElementById('formsCatalogueEl');
  if(!el)return;
  let html='';
  for(const cat of FORMS_CAT){
    if(cat.fsp.startsWith('_'))continue;
    const vis=cat.forms.filter(f=>!q||f.name.toLowerCase().includes(q)||f.desc.toLowerCase().includes(q)||cat.fsp.toLowerCase().includes(q));
    if(!vis.length)continue;
    html+=`<div style="margin-bottom:18px;">
      <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.7px;color:${cat.color};margin-bottom:7px;padding-left:2px;">${cat.fsp}</div>
      ${vis.map(f=>`
        <div onclick="openForm('${f.id}')" style="display:flex;align-items:center;gap:10px;padding:11px 13px;background:#fff;border:1px solid #e5e7eb;border-left:3px solid ${cat.color};border-radius:8px;margin-bottom:6px;cursor:pointer;" onmouseover="this.style.background='#f9fafb'" onmouseout="this.style.background='#fff'">
          <div style="flex:1;">
            <div style="font-size:13px;font-weight:600;color:#111827;">${f.name}</div>
            <div style="font-size:11px;color:#6b7280;margin-top:2px;">${f.desc}</div>
          </div>
          <div style="color:#d1d5db;font-size:20px;line-height:1;">›</div>
        </div>`).join('')}
    </div>`;
  }
  el.innerHTML=html||'<div style="text-align:center;padding:40px 0;color:#9ca3af;font-size:13px;">No forms found</div>';
}

function filterForms(q){ renderFormsPage(); }

// ── Shared form helpers ──────────────────────

function _fs(){
  // Shared inline styles injected once per form
  return `<style>
    .fd{font-family:Arial,sans-serif;font-size:13px;color:#111;max-width:700px;margin:0 auto;background:#fff;padding:20px 22px;border-radius:10px;box-shadow:0 1px 8px rgba(0,0,0,.1);}
    .fu{border:none;border-bottom:1.5px solid #555;background:transparent;font-size:12.5px;padding:2px 3px;outline:none;font-family:Arial,sans-serif;color:#111;}
    .fbox{border:1px solid #aaa;border-radius:2px;background:#fff;font-size:12.5px;padding:4px 6px;outline:none;font-family:Arial,sans-serif;color:#111;}
    .ffr{display:flex;align-items:center;gap:8px;margin-bottom:8px;}
    .ffr label{white-space:nowrap;font-size:12px;font-weight:600;min-width:78px;}
    .fsec{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;background:#f0f0f0;border:1px solid #ccc;padding:5px 8px;margin:14px 0 8px;}
    .sig-wrap{margin-top:6px;}
    .sig-wrap canvas{border:1px solid #aaa;border-radius:3px;cursor:crosshair;display:block;touch-action:none;background:#fff;}
    .sig-wrap button{font-size:10px;color:#888;background:none;border:none;cursor:pointer;padding:2px 0;}
    @media print{.no-print{display:none!important;}}
  </style>`;
}

function _sigBlock(id,w=240,h=75){
  return `<div class="sig-wrap">
    <canvas id="${id}" data-sig="1" width="${w}" height="${h}"></canvas>
    <button class="no-print" onclick="clearCanvas('${id}')">✕ Clear</button>
  </div>`;
}

function _today(){ return new Date().toISOString().slice(0,10); }

// ── Open / close / print ────────────────────

function openForm(id){
  const overlay=document.getElementById('formViewerOverlay');
  if(!overlay)return;
  const u=currentUser||{};
  const today=_today();
  const MAP={
    cancel_letter:   {title:'Cancellation Letter',              html:_form_cancel_letter(u,today)},
    refund_letter:   {title:'Refund Request Letter',            html:_form_refund_letter(u,today)},
    precan_reversal: {title:'Pre-Cancellation Reversal',        html:_form_precan_reversal(u,today)},
    wl_cancel:       {title:'Workers Life — Cancellation Request', html:_form_wl_cancel(u,today)},
    wl_payment:      {title:'Workers Life — Payment Mandate',   html:_form_wl_payment(u,today)},
    assupol_debit:   {title:'Assupol — Debit Order Authorization', html:_form_assupol_debit(u,today)},
    sansky_cancel:   {title:'Sanlam Sky — Cancellation Letter', html:_form_sansky_cancel(u,today)},
    sansky_banking:  {title:'Sanlam Sky — Banking Details Change', html:_form_sansky_banking(u,today)},
    sanlife_cancel:  {title:'Sanlam Life — Cancellation Letter',html:_form_sanlife_cancel(u,today)},
    saps_cancel:     {title:'SAPS — Cancellation Form',         html:_form_saps_cancel(u,today)},
    metro_debit:     {title:'Metropolitan — Bank Debit Order',  html:_form_metro_debit(u,today)},
    metro_paidup:    {title:'Metropolitan — Policy Paid-Up',    html:_form_metro_paidup(u,today)},
    metro_surrender: {title:'Metropolitan — Full Surrender',    html:_form_metro_surrender(u,today)},
    hsl_debit:       {title:'Hollard Specialist — Debit Order Authorisation', html:_form_hsl_debit(u,today)},
    hsl_surrender:   {title:'Hollard Specialist — Surrender Application',     html:_form_hsl_surrender(u,today)},
    avbob_debit:     {title:'AVBOB — Debit Order Authorisation',html:_form_avbob_debit(u,today)},
    avbob_surrender: {title:'AVBOB — Surrender Application',   html:_form_avbob_surrender(u,today)},
    repl_disclosure: {title:'Replacement Disclosure & Client Acknowledgment', html:_form_repl_disclosure(u,today)},
  };
  const form=MAP[id];if(!form)return;
  document.getElementById('fvBarTitle').textContent=form.title;
  document.getElementById('fvContent').innerHTML=form.html;
  overlay.style.display='flex';
  document.querySelectorAll('canvas[data-sig]').forEach(c=>initSigCanvas(c.id));
}

function closeFormViewer(){
  const o=document.getElementById('formViewerOverlay');
  if(o){o.style.display='none';}
  document.getElementById('fvContent').innerHTML='';
}

function printForm(){ window.print(); }

function initSigCanvas(id){
  const c=document.getElementById(id);
  if(!c||c._si)return;
  c._si=true;
  const ctx=c.getContext('2d');
  ctx.strokeStyle='#111';ctx.lineWidth=2;ctx.lineCap='round';ctx.lineJoin='round';
  let d=false,lx=0,ly=0;
  const gp=e=>{const r=c.getBoundingClientRect();return e.touches?[e.touches[0].clientX-r.left,e.touches[0].clientY-r.top]:[e.clientX-r.left,e.clientY-r.top];};
  c.addEventListener('mousedown',e=>{d=true;[lx,ly]=gp(e);});
  c.addEventListener('mousemove',e=>{if(!d)return;const [x,y]=gp(e);ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(x,y);ctx.stroke();[lx,ly]=[x,y];});
  c.addEventListener('mouseup',()=>d=false);
  c.addEventListener('mouseleave',()=>d=false);
  c.addEventListener('touchstart',e=>{e.preventDefault();d=true;[lx,ly]=gp(e);},{passive:false});
  c.addEventListener('touchmove',e=>{if(!d)return;e.preventDefault();const [x,y]=gp(e);ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(x,y);ctx.stroke();[lx,ly]=[x,y];},{passive:false});
  c.addEventListener('touchend',()=>d=false);
}

function clearCanvas(id){
  const c=document.getElementById(id);
  if(c)c.getContext('2d').clearRect(0,0,c.width,c.height);
}

